@@ -0,0 +1,180 @@
+"use client";
+
+import { useCallback, useEffect, useRef, useState } from "react";
+import { subDays, startOfDay, endOfDay } from "date-fns";
+import {
+  AuditLogFiltersBar,
+  type AuditLogFilters,
+} from "@/components/audit/audit-log-filters";
+import { AuditLogTable } from "@/components/audit/audit-log-table";
+import { AuditLogExportButton } from "@/components/audit/audit-log-export-button";
+import type { AuditLogEntry } from "@/types/audit";
+import type { PaginatedResponse } from "@/types/api";
+
+interface TeamMember {
+  id: string;
+  name: string;
+  email: string;
+}
+
+const PAGE_SIZE = 20;
+
+function defaultFilters(): AuditLogFilters {
+  return {
+    from: startOfDay(subDays(new Date(), 30)),
+    to: endOfDay(new Date()),
+    userId: "",
+    action: "",
+  };
+}
+
+function buildQuery(filters: AuditLogFilters, cursor: string | null) {
+  const params = new URLSearchParams();
+  params.set("startDate", filters.from.toISOString());
+  params.set("endDate", filters.to.toISOString());
+  if (filters.userId) params.set("userId", filters.userId);
+  if (filters.action) params.set("action", filters.action);
+  params.set("limit", String(PAGE_SIZE));
+  if (cursor) params.set("cursor", cursor);
+  return params.toString();
+}
+
+export default function AuditLogPage() {
+  const [filters, setFilters] = useState<AuditLogFilters>(defaultFilters());
+  const [entries, setEntries] = useState<AuditLogEntry[]>([]);
+  const [users, setUsers] = useState<TeamMember[]>([]);
+  const [cursor, setCursor] = useState<string | null>(null);
+  const [hasMore, setHasMore] = useState(false);
+  const [isLoading, setIsLoading] = useState(true);
+  const [isLoadingMore, setIsLoadingMore] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const [helpUrl, setHelpUrl] = useState<string | null>(null);
+  const [forbidden, setForbidden] = useState(false);
+
+  // Guards against stale responses overwriting newer filter results.
+  const requestId = useRef(0);
+
+  const fetchPage = useCallback(
+    async (nextFilters: AuditLogFilters, nextCursor: string | null) => {
+      const currentRequest = ++requestId.current;
+      nextCursor ? setIsLoadingMore(true) : setIsLoading(true);
+      setError(null);
+
+      try {
+        const response = await fetch(
+          `/api/audit?${buildQuery(nextFilters, nextCursor)}`
+        );
+
+        if (currentRequest !== requestId.current) return;
+
+        if (response.status === 403) {
+          setForbidden(true);
+          setIsLoading(false);
+          setIsLoadingMore(false);
+          return;
+        }
+
+        if (!response.ok) {
+          const body = await response.json().catch(() => null);
+          setError(body?.error || "Failed to load audit log.");
+          setHelpUrl(body?.help || null);
+          setIsLoading(false);
+          setIsLoadingMore(false);
+          return;
+        }
+
+        const page: PaginatedResponse<AuditLogEntry> = await response.json();
+
+        setEntries((prev) => (nextCursor ? [...prev, ...page.data] : page.data));
+        setCursor(page.nextCursor);
+        setHasMore(page.hasMore);
+      } catch {
+        if (currentRequest !== requestId.current) return;
+        setError("Failed to load audit log. Please try again.");
+        setHelpUrl("https://help.example.com/errors/EXPORT_001");
+      } finally {
+        if (currentRequest === requestId.current) {
+          setIsLoading(false);
+          setIsLoadingMore(false);
+        }
+      }
+    },
+    []
+  );
+
+  useEffect(() => {
+    fetchPage(filters, null);
+  }, [filters, fetchPage]);
+
+  useEffect(() => {
+    fetch("/api/users?limit=100")
+      .then((res) => (res.ok ? res.json() : null))
+      .then((page: PaginatedResponse<TeamMember> | null) => {
+        if (page) setUsers(page.data);
+      })
+      .catch(() => {
+        // Non-critical — the user filter just won't have options.
+      });
+  }, []);
+
+  const handleLoadMore = () => {
+    if (cursor) fetchPage(filters, cursor);
+  };
+
+  if (forbidden) {
+    return (
+      <div className="space-y-6">
+        <div>
+          <h2 className="text-2xl font-bold text-gray-900">Audit Log</h2>
+        </div>
