@@ -0,0 +1,83 @@
+"use client";
+
+import { Download } from "lucide-react";
+import { Button } from "@/components/ui/button";
+import { useToast } from "@/hooks/use-toast";
+
+interface AuditLogExportButtonProps {
+  from: Date;
+  to: Date;
+  userId?: string;
+  action?: string;
+  format?: "csv" | "json";
+}
+
+/**
+ * Export button for the audit log itself.
+ *
+ * IMPORTANT: The server-side export endpoint (/api/audit/export) wraps the
+ * export in `withAuditLog` to comply with data governance policy DG-003 —
+ * exporting the audit log is still a data export. See
+ * src/app/api/audit/export/route.ts.
+ *
+ * Uses variant="secondary" because this is a read-only/export action, not
+ * a mutation. See Button component conventions.
+ */
+export function AuditLogExportButton({
+  from,
+  to,
+  userId,
+  action,
+  format = "csv",
+}: AuditLogExportButtonProps) {
+  const toast = useToast();
+
+  const handleExport = async () => {
+    try {
+      toast.loading("Preparing export...");
+
+      const response = await fetch("/api/audit/export", {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify({
+          startDate: from.toISOString(),
+          endDate: to.toISOString(),
+          userId: userId || undefined,
+          action: action || undefined,
+          format,
+        }),
+      });
+
+      if (!response.ok) {
+        const error = await response.json();
+        toast.error(
+          error.help
+            ? `Export failed. See ${error.help}`
+            : "Export failed. Please try again."
+        );
+        return;
+      }
+
+      const blob = await response.blob();
+      const url = URL.createObjectURL(blob);
+      const a = document.createElement("a");
+      a.href = url;
+      a.download = `audit-log-export.${format}`;
+      a.click();
+      URL.revokeObjectURL(url);
+
+      toast.success("Audit log exported successfully");
+    } catch {
+      toast.error(
+        "Export failed. See https://help.example.com/errors/EXPORT_001"
+      );
+    }
+  };
+
+  return (
+    <Button variant="secondary" onClick={handleExport}>
+      <Download className="mr-2 h-4 w-4" />
+      Export audit log
+    </Button>
+  );
+}
