+"use client";
+
+import { format } from "date-fns";
+import { Badge } from "@/components/ui/badge";
+import { Button } from "@/components/ui/button";
+import { AuditLogTableSkeleton } from "./audit-log-table-skeleton";
+import type { AuditLogEntry } from "@/types/audit";
+import { AUDIT_ACTIONS } from "@/types/audit";
+
+function formatTimestamp(date: string): string {
+  return format(new Date(date), "MMM d, yyyy 'at' h:mm a");
+}
+
+interface AuditLogTableProps {
+  entries: AuditLogEntry[];
+  isLoading: boolean;
+  isLoadingMore: boolean;
+  error: string | null;
+  helpUrl: string | null;
+  hasMore: boolean;
+  onLoadMore: () => void;
+}
+
+function actionLabel(action: string): string {
+  return AUDIT_ACTIONS.find((a) => a.value === action)?.label || action;
+}
+
+export function AuditLogTable({
+  entries,
+  isLoading,
+  isLoadingMore,
+  error,
+  helpUrl,
+  hasMore,
+  onLoadMore,
+}: AuditLogTableProps) {
+  if (isLoading) {
+    return <AuditLogTableSkeleton />;
+  }
+
+  if (error) {
+    return (
+      <div className="rounded-lg border border-red-200 bg-red-50 p-6 text-center">
+        <p className="text-sm font-medium text-red-700">{error}</p>
+        {helpUrl && (
+          <a
+            href={helpUrl}
+            className="mt-1 inline-block text-sm text-red-600 underline"
+          >
+            Learn more
+          </a>
+        )}
+      </div>
+    );
+  }
+
+  if (entries.length === 0) {
+    return (
+      <div className="rounded-lg border border-gray-200 bg-white p-10 text-center">
+        <p className="text-sm text-gray-500">
+          No audit log entries match the current filters.
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <div className="space-y-3">
+      <div className="overflow-hidden rounded-lg border border-gray-200 bg-white">
+        <table className="w-full text-sm">
+          <thead className="border-b border-gray-200 bg-gray-50">
+            <tr>
+              <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+                User
+              </th>
+              <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+                Action
+              </th>
+              <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+                Resource
+              </th>
+              <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+                IP Address
+              </th>
+              <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+                Date
+              </th>
+            </tr>
+          </thead>
+          <tbody className="divide-y divide-gray-100">
+            {entries.map((entry) => {
+              const status =
+                entry.metadata && typeof entry.metadata.status === "string"
+                  ? (entry.metadata.status as string)
+                  : null;
+
+              return (
+                <tr key={entry.id}>
+                  <td className="px-4 py-3">
+                    <div className="font-medium text-gray-900">
+                      {entry.userName || "Unknown user"}
+                    </div>
+                    <div className="text-xs text-gray-400">
+                      {entry.userEmail || entry.userId}
+                    </div>
+                  </td>
+                  <td className="px-4 py-3">
+                    <div className="flex items-center gap-2">
+                      <span className="text-gray-700">
+                        {actionLabel(entry.action)}
+                      </span>
+                      {status === "error" && (
+                        <Badge variant="error">failed</Badge>
+                      )}
+                      {status === "success" && (
+                        <Badge variant="success">success</Badge>
+                      )}
+                    </div>
+                  </td>
+                  <td className="px-4 py-3 text-gray-700">
+                    {entry.resourceType}
+                    {entry.resourceId ? ` · ${entry.resourceId}` : ""}
+                  </td>
+                  <td className="px-4 py-3 text-gray-500">
+                    {entry.ipAddress || "—"}
+                  </td>
+                  <td className="px-4 py-3 text-gray-500">
+                    {formatTimestamp(entry.createdAt)}
+                  </td>
+                </tr>
+              );
+            })}
+          </tbody>
+        </table>
+      </div>
+
+      {hasMore && (
+        <div className="flex justify-center">
+          <Button
+            variant="secondary"
+            onClick={onLoadMore}
+            disabled={isLoadingMore}
+          >
+            {isLoadingMore ? "Loading..." : "Load more"}
+          </Button>
+        </div>
+      )}
+    </div>
+  );
+}
