+import { describe, it, expect } from "vitest";
+import { auditLogQuerySchema, exportAuditLogSchema } from "./audit";
+
+describe("audit validators", () => {
+  describe("auditLogQuerySchema", () => {
+    it("should accept an empty filter set", () => {
+      const result = auditLogQuerySchema.safeParse({});
+      expect(result.success).toBe(true);
+    });
+
+    it("should accept userId and action filters", () => {
+      const result = auditLogQuerySchema.safeParse({
+        userId: "user-1",
+        action: "export_analytics",
+      });
+      expect(result.success).toBe(true);
+    });
+
+    it("should coerce date strings", () => {
+      const result = auditLogQuerySchema.parse({
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+      });
+      expect(result.startDate).toBeInstanceOf(Date);
