+import { z } from "zod";
+
+/**
+ * Query filters for GET /api/audit — filter by date range, user, and
+ * action type. See src/app/audit/page.tsx for the admin viewer UI.
+ */
+export const auditLogQuerySchema = z.object({
+  userId: z.string().optional(),
+  action: z.string().optional(),
+  startDate: z.coerce.date().optional(),
+  endDate: z.coerce.date().optional(),
+});
+
+/**
+ * Export payload for POST /api/audit/export.
+ *
+ * IMPORTANT: exporting the audit log is itself a data export and MUST be
+ * wrapped in `withAuditLog` per DG-003 — see src/app/api/audit/export/route.ts.
+ */
+export const exportAuditLogSchema = z.object({
+  format: z.enum(["csv", "json"]).default("csv"),
+  startDate: z.coerce.date().optional(),
+  endDate: z.coerce.date().optional(),
+  userId: z.string().optional(),
+  action: z.string().optional(),
+});
+
+export type AuditLogQuery = z.infer<typeof auditLogQuerySchema>;
+export type ExportAuditLogInput = z.infer<typeof exportAuditLogSchema>;
