+/**
+ * Audit log types.
+ *
+ * See src/lib/audit-log/index.ts for the `withAuditLog` middleware that
+ * writes these entries. Per data governance policy DG-003, every data
+ * export (including exporting the audit log itself) must be wrapped in
+ * `withAuditLog`.
+ */
+
+export interface AuditLogEntry {
+  id: string;
+  userId: string;
+  /** Display name of the user who performed the action, if resolvable. */
+  userName: string | null;
+  /** Email of the user who performed the action, if resolvable. */
+  userEmail: string | null;
+  action: string;
+  resourceType: string;
+  resourceId: string | null;
+  metadata: Record<string, unknown> | null;
+  ipAddress: string | null;
+  createdAt: string;
+}
+
+/**
+ * Known audit log action types, used to populate the action filter.
+ * The underlying column is free-form text, so this list is a curated
+ * subset of actions actually emitted by `withAuditLog` call sites —
+ * it is not a DB-level enum.
+ */
+export const AUDIT_ACTIONS = [
+  { value: "export_analytics", label: "Export Analytics" },
+  { value: "export_audit_log", label: "Export Audit Log" },
+] as const;
+
+export type AuditAction = (typeof AUDIT_ACTIONS)[number]["value"];

diff --git a/src/app/api/analytics/export/preview/route.ts b/src/app/api/analytics/export/preview/route.ts
new file mode 100644
index 0000000..cc3feae
--- /dev/null
+++ b/src/app/api/analytics/export/preview/route.ts
@@ -0,0 +1,68 @@
+import { NextRequest } from "next/server";
+import { count } from "drizzle-orm";
+import { db } from "@/lib/db";
+import { analyticsEvents } from "@/lib/db/schema";
+import { eq, and, gte, lte } from "drizzle-orm";
+import { withAuth } from "@/lib/auth/with-auth";
+import {
+  exportPreviewSchema,
+  EXPORT_ROW_LIMIT,
+} from "@/lib/validators/analytics";
+import { errorResponse } from "@/lib/errors";
+import { jsonResponse } from "@/lib/api/response";
+
+/**
+ * GET /api/analytics/export/preview — count how many rows a CSV/JSON export
+ * for a given date range would return, without returning any underlying
+ * records.
+ *
+ * NOTE: intentionally NOT wrapped in `withAuditLog`. Policy DG-003 requires
+ * auditing actual data exports (POST /api/analytics/export); this endpoint
+ * only exposes an aggregate count so users can size their export before
+ * requesting it, so no row-level data leaves the server.
+ */
+export const GET = withAuth(async (req: NextRequest, { user }) => {
+  const url = new URL(req.url);
+
+  const eventTypesParam = url.searchParams.get("eventTypes");
+  const parsed = exportPreviewSchema.safeParse({
+    startDate: url.searchParams.get("startDate") || undefined,
+    endDate: url.searchParams.get("endDate") || undefined,
+    eventTypes: eventTypesParam ? eventTypesParam.split(",") : undefined,
+  });
+
+  if (!parsed.success) {
+    return errorResponse("VAL_001", 400, parsed.error.issues[0].message);
+  }
+
+  const { startDate, endDate, eventTypes } = parsed.data;
+
+  if (startDate > endDate) {
+    return errorResponse("VAL_001", 400, "startDate must be before endDate");
+  }
+
+  const conditions = [];
+
+  if (user.teamId) {
+    conditions.push(eq(analyticsEvents.teamId, user.teamId));
+  }
+  conditions.push(gte(analyticsEvents.createdAt, startDate));
+  conditions.push(lte(analyticsEvents.createdAt, endDate));
+
+  // Mirrors the export endpoint's current filter behavior (first event type
+  // only) so the preview count matches what the export will actually return.
+  if (eventTypes && eventTypes.length > 0) {
+    conditions.push(eq(analyticsEvents.eventType, eventTypes[0]));
+  }
+
+  const [{ value: total }] = await db
+    .select({ value: count() })
+    .from(analyticsEvents)
+    .where(and(...conditions));
+
+  return jsonResponse({
+    count: total,
+    limit: EXPORT_ROW_LIMIT,
+    exceedsLimit: total > EXPORT_ROW_LIMIT,
+  });
+});
