+++ b/src/app/audit/page.tsx
@@ -0,0 +1,153 @@
+"use client";
+
+import { useCallback, useEffect, useState } from "react";
+import { ShieldAlert } from "lucide-react";
+import { AuditLogTable } from "@/components/audit/audit-log-table";
+import { AuditLogFilters } from "@/components/audit/audit-log-filters";
+import { AuditLogExportButton } from "@/components/audit/audit-log-export-button";
+import { Button } from "@/components/ui/button";
+import { useDateRange } from "@/hooks/use-date-range";
+import { useToast } from "@/hooks/use-toast";
+import type { AuditLogEntry, AuditLogFilterOptions } from "@/types/audit-log";
+import type { PaginatedResponse } from "@/types/api";
+
+const ALL = "all";
+
+const EMPTY_OPTIONS: AuditLogFilterOptions = { users: [], actions: [] };
+
+export default function AuditLogPage() {
+  const { range: dateRange, setCustomRange } = useDateRange("30d");
+  const [userId, setUserId] = useState(ALL);
+  const [action, setAction] = useState(ALL);
+
+  const [options, setOptions] = useState<AuditLogFilterOptions>(EMPTY_OPTIONS);
+  const [entries, setEntries] = useState<AuditLogEntry[]>([]);
+  const [nextCursor, setNextCursor] = useState<string | null>(null);
+  const [hasMore, setHasMore] = useState(false);
+  const [loading, setLoading] = useState(true);
+  const [loadingMore, setLoadingMore] = useState(false);
+  const [forbidden, setForbidden] = useState(false);
+
+  const toast = useToast();
+
+  const buildParams = useCallback(
+    (cursor?: string) => {
+      const params = new URLSearchParams();
+      params.set("startDate", dateRange.from.toISOString());
+      params.set("endDate", dateRange.to.toISOString());
+      if (userId !== ALL) params.set("userId", userId);
+      if (action !== ALL) params.set("action", action);
+      if (cursor) params.set("cursor", cursor);
+      return params;
+    },
+    [dateRange, userId, action]
+  );
+
+  const fetchEntries = useCallback(
+    async (cursor?: string) => {
+      const append = Boolean(cursor);
+      append ? setLoadingMore(true) : setLoading(true);
+
+      try {
+        const res = await fetch(`/api/audit-logs?${buildParams(cursor)}`);
+
+        if (res.status === 403) {
+          setForbidden(true);
+          return;
+        }
+
+        if (!res.ok) {
+          toast.error("Failed to load audit log. Please try again.");
+          return;
+        }
+
+        const page: PaginatedResponse<AuditLogEntry> = await res.json();
+        setEntries((prev) => (append ? [...prev, ...page.data] : page.data));
+        setNextCursor(page.nextCursor);
+        setHasMore(page.hasMore);
+        setForbidden(false);
+      } catch {
+        toast.error("Failed to load audit log. Please try again.");
+      } finally {
+        append ? setLoadingMore(false) : setLoading(false);
+      }
+    },
+    [buildParams, toast]
+  );
+
+  // Load filter options once.
+  useEffect(() => {
+    fetch("/api/audit-logs/meta")
+      .then((res) => (res.status === 403 ? EMPTY_OPTIONS : res.json()))
+      .then((data: AuditLogFilterOptions) => setOptions(data))
+      .catch(() => setOptions(EMPTY_OPTIONS));
+  }, []);
+
+  // Refetch (from the start) whenever filters change.
+  useEffect(() => {
+    fetchEntries();
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [dateRange, userId, action]);
+
+  if (forbidden) {
+    return (
+      <div className="flex h-64 flex-col items-center justify-center gap-3 rounded-lg border border-gray-200 bg-white text-center">
+        <ShieldAlert className="h-10 w-10 text-gray-400" />
+        <div>
+          <p className="font-medium text-gray-900">Admins only</p>
+          <p className="text-sm text-gray-500">
+            You don&apos;t have permission to view the audit log.
+          </p>
+        </div>
+      </div>
+    );
+  }
+
+  return (
+    <div className="space-y-6">
+      <div className="flex items-center justify-between">
+        <div>
+          <h2 className="text-2xl font-bold text-gray-900">Audit Log</h2>
+          <p className="text-sm text-gray-500">
+            Track who exported what data, and when.
+          </p>
+        </div>
+        {/* variant="secondary" for read-only/export action */}
+        <AuditLogExportButton
+          startDate={dateRange.from}
+          endDate={dateRange.to}
+          userId={userId !== ALL ? userId : undefined}
+          action={action !== ALL ? action : undefined}
+        />
+      </div>
+
+      <AuditLogFilters
+        dateRange={dateRange}
+        onDateRangeChange={({ from, to }) => setCustomRange(from, to)}
+        userId={userId}
+        onUserIdChange={setUserId}
+        action={action}
+        onActionChange={setAction}
+        options={options}
+        onReset={() => {
+          setUserId(ALL);
+          setAction(ALL);
+        }}
+      />
+
+      <AuditLogTable entries={entries} loading={loading} />
+
+      {!loading && hasMore && (
+        <div className="flex justify-center">
+          <Button
+            variant="secondary"
+            onClick={() => nextCursor && fetchEntries(nextCursor)}
+            disabled={loadingMore}
+          >
+            {loadingMore ? "Loading..." : "Load more"}
+          </Button>
+        </div>
+      )}
+    </div>
+  );
+}
