+import { Badge } from "@/components/ui/badge";
+import { ShimmerSkeleton } from "@/components/ui/shimmer-skeleton";
+import { formatActionLabel, formatDate, formatRelativeDate } from "@/lib/utils";
+import type { AuditLogEntry } from "@/types/audit-log";
+
+interface AuditLogTableProps {
+  entries: AuditLogEntry[];
+  /** Show skeleton rows in place of data (initial load / filter change). */
+  loading?: boolean;
+  skeletonRows?: number;
+}
+
+const COLUMNS = ["User", "Action", "Resource", "Status", "IP Address", "Date"];
+
+/**
+ * Table of audit log entries — who exported/changed what, and when.
+ *
+ * While `loading` is true, renders shimmer skeleton rows instead of data
+ * (and instead of the empty state) so the table never flashes "No entries".
+ */
+export function AuditLogTable({
+  entries,
+  loading = false,
+  skeletonRows = 8,
+}: AuditLogTableProps) {
+  return (
+    <div className="overflow-hidden rounded-lg border border-gray-200 bg-white">
+      <table className="w-full text-left text-sm">
+        <thead className="border-b border-gray-200 bg-gray-50">
+          <tr>
+            {COLUMNS.map((col) => (
+              <th
+                key={col}
+                scope="col"
+                className="px-4 py-3 font-medium text-gray-500"
+              >
+                {col}
+              </th>
+            ))}
+          </tr>
+        </thead>
+        <tbody className="divide-y divide-gray-100">
+          {loading ? (
+            Array.from({ length: skeletonRows }).map((_, i) => (
+              <tr key={i} data-testid="audit-log-skeleton-row">
+                {COLUMNS.map((col) => (
+                  <td key={col} className="px-4 py-3">
+                    <ShimmerSkeleton variant="text" height="14px" />
+                  </td>
+                ))}
+              </tr>
+            ))
+          ) : entries.length === 0 ? (
+            <tr>
+              <td
+                colSpan={COLUMNS.length}
+                className="px-4 py-10 text-center text-gray-500"
+              >
+                No audit log entries match these filters.
+              </td>
+            </tr>
+          ) : (
+            entries.map((entry) => <AuditLogRow key={entry.id} entry={entry} />)
+          )}
+        </tbody>
+      </table>
+    </div>
+  );
+}
+
+function AuditLogRow({ entry }: { entry: AuditLogEntry }) {
+  const status = (entry.metadata?.status as string | undefined) ?? null;
+
+  return (
+    <tr className="hover:bg-gray-50">
+      <td className="px-4 py-3">
+        <div className="font-medium text-gray-900">{entry.userName}</div>
+        <div className="text-xs text-gray-500">{entry.userEmail}</div>
+      </td>
+      <td className="px-4 py-3">
+        <Badge variant="neutral">{formatActionLabel(entry.action)}</Badge>
+      </td>
+      <td className="px-4 py-3 text-gray-700">
+        {entry.resourceType}
+        {entry.resourceId ? (
+          <span className="text-gray-400"> · {entry.resourceId}</span>
+        ) : null}
+      </td>
+      <td className="px-4 py-3">
+        {status === "success" ? (
+          <Badge variant="success">Success</Badge>
+        ) : status === "error" ? (
+          <Badge variant="error">Failed</Badge>
+        ) : (
+          <span className="text-gray-400">—</span>
+        )}
+      </td>
+      <td className="px-4 py-3 text-gray-500">{entry.ipAddress ?? "—"}</td>
+      <td className="px-4 py-3">
+        <div className="text-gray-700">{formatDate(entry.createdAt)}</div>
+        <div className="text-xs text-gray-400">
+          {formatRelativeDate(entry.createdAt)}
+        </div>
+      </td>
+    </tr>
+  );
+}
