+import { NextRequest } from "next/server";
+import { db } from "@/lib/db";
+import { analyticsEvents } from "@/lib/db/schema";
+import { eq, and, gte, lte, count } from "drizzle-orm";
+import { withAuth } from "@/lib/auth/with-auth";
+import { exportCountQuerySchema } from "@/lib/validators/analytics";
+import { errorResponse } from "@/lib/errors";
+import { jsonResponse } from "@/lib/api/response";
+
+/**
+ * GET /api/analytics/export/count — preview how many records a given
+ * date range would produce before actually exporting them.
+ *
+ * This mirrors the filtering logic in POST /api/analytics/export so the
+ * previewed count matches the eventual export. It only returns an
+ * aggregate count (no row data leaves the server), so it does not need
+ * to go through `withAuditLog` like the actual export endpoint does.
+ */
+export const GET = withAuth(async (req: NextRequest, { user }) => {
+  const url = new URL(req.url);
+
+  const parsed = exportCountQuerySchema.safeParse({
+    startDate: url.searchParams.get("startDate") || undefined,
+    endDate: url.searchParams.get("endDate") || undefined,
+  });
+
+  if (!parsed.success) {
+    return errorResponse("VAL_001", 400, parsed.error.issues[0].message);
+  }
+
+  const { startDate, endDate } = parsed.data;
+
+  const conditions = [];
+
+  if (user.teamId) {
+    conditions.push(eq(analyticsEvents.teamId, user.teamId));
+  }
+  conditions.push(gte(analyticsEvents.createdAt, startDate));
+  conditions.push(lte(analyticsEvents.createdAt, endDate));
+
+  const [{ value }] = await db
+    .select({ value: count() })
+    .from(analyticsEvents)
+    .where(and(...conditions));
+
+  return jsonResponse({ count: value });
+});
