+                onChange={(e) => setRangeTo(e.target.value)}
+                min={rangeFrom || undefined}
+                className="w-full rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
+              />
+            </div>
+          </div>
+
+          <div className="rounded-md bg-gray-50 px-3 py-2 text-sm text-gray-600">
+            {isPreviewLoading && "Counting records..."}
+            {!isPreviewLoading && previewError && (
+              <span className="text-red-600">{previewError}</span>
+            )}
+            {!isPreviewLoading && !previewError && previewCount !== null && (
+              <>
+                <span className="font-semibold text-gray-900">
+                  {previewCount.toLocaleString()}
+                </span>{" "}
+                {previewCount === 1 ? "record" : "records"} will be exported
+              </>
+            )}
+          </div>
+
+          <div className="flex justify-end gap-2">
+            <Button
+              variant="ghost"
+              size="sm"
+              onClick={() => setIsOpen(false)}
+              disabled={isExporting}
+            >
+              Cancel
+            </Button>
+            {/* variant="secondary" for read-only/export action */}
+            <Button
+              variant="secondary"
+              size="sm"
+              onClick={handleExport}
+              disabled={
+                !rangeFrom ||
+                !rangeTo ||
+                isExporting ||
+                previewCount === 0
+              }
+            >
+              <Download className="mr-2 h-4 w-4" />
+              {isExporting ? "Downloading..." : "Download CSV"}
+            </Button>
+          </div>
+        </div>
+      </Dialog>
+    </>
   );
 }
+
+function formatInputDate(date: Date): string {
+  return date.toISOString().split("T")[0];
+}
