diff --git a/src/app/audit/page.tsx b/src/app/audit/page.tsx
new file mode 100644
index 0000000..af9b576
--- /dev/null
+++ b/src/app/audit/page.tsx
@@ -0,0 +1,186 @@
+"use client";
+
+import { useCallback, useEffect, useState } from "react";
+import { Shield } from "lucide-react";
+import { AuditLogFilters } from "@/components/audit/audit-log-filters";
+import { AuditLogTable } from "@/components/audit/audit-log-table";
+import { AuditLogSkeleton } from "@/components/audit/audit-log-skeleton";
+import { AuditLogExportButton } from "@/components/audit/audit-log-export-button";
+import { Button } from "@/components/ui/button";
+import { useDateRange } from "@/hooks/use-date-range";
+import type { AuditLogEntry } from "@/types/audit-log";
+import type { PaginatedResponse, ApiError } from "@/types/api";
+
+interface UserOption {
+  id: string;
+  name: string;
+}
+
+export default function AuditLogPage() {
+  const { range, setCustomRange } = useDateRange("30d");
+  const [userId, setUserId] = useState("");
+  const [action, setAction] = useState("");
+
+  const [users, setUsers] = useState<UserOption[]>([]);
+  const [entries, setEntries] = useState<AuditLogEntry[]>([]);
+  const [cursor, setCursor] = useState<string | null>(null);
+  const [hasMore, setHasMore] = useState(false);
+  const [loading, setLoading] = useState(true);
+  const [loadingMore, setLoadingMore] = useState(false);
+  const [forbidden, setForbidden] = useState(false);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+
+  // Populate the user filter from the team roster.
+  useEffect(() => {
+    fetch("/api/users")
+      .then((res) => (res.ok ? res.json() : null))
+      .then((page: PaginatedResponse<UserOption> | null) => {
+        if (page) setUsers(page.data.map((u) => ({ id: u.id, name: u.name })));
+      })
+      .catch(() => {
+        // Non-fatal — the user filter just won't have options.
+      });
+  }, []);
+
+  const fetchPage = useCallback(
+    async (nextCursor: string | null) => {
+      const params = new URLSearchParams({
+        startDate: range.from.toISOString(),
+        endDate: range.to.toISOString(),
+        limit: "20",
+      });
+      if (userId) params.set("userId", userId);
+      if (action) params.set("action", action);
+      if (nextCursor) params.set("cursor", nextCursor);
+
+      const response = await fetch(`/api/audit-log?${params.toString()}`);
+
+      if (!response.ok) {
+        const error: ApiError = await response.json();
+        if (response.status === 403) {
+          setForbidden(true);
+        } else {
+          setErrorMessage(
+            error.help ? `Failed to load audit log. See ${error.help}` : "Failed to load audit log."
+          );
+        }
+        return null;
+      }
+
+      return (await response.json()) as PaginatedResponse<AuditLogEntry>;
+    },
+    [range.from, range.to, userId, action]
+  );
+
+  // Reload from scratch whenever filters change.
+  useEffect(() => {
+    let cancelled = false;
+    setLoading(true);
+    setForbidden(false);
+    setErrorMessage(null);
+
+    fetchPage(null).then((page) => {
+      if (cancelled || !page) {
+        if (!cancelled) setLoading(false);
+        return;
+      }
+      setEntries(page.data);
+      setCursor(page.nextCursor);
+      setHasMore(page.hasMore);
+      setLoading(false);
+    });
+
+    return () => {
+      cancelled = true;
+    };
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [range.from, range.to, userId, action]);
+
+  const handleLoadMore = async () => {
+    setLoadingMore(true);
+    const page = await fetchPage(cursor);
+    if (page) {
+      setEntries((prev) => [...prev, ...page.data]);
+      setCursor(page.nextCursor);
+      setHasMore(page.hasMore);
+    }
+    setLoadingMore(false);
+  };
+
+  const handleClearFilters = () => {
+    setUserId("");
+    setAction("");
+  };
+
+  return (
+    <div className="space-y-6">
+      <div className="flex items-center justify-between">
+        <div>
+          <h2 className="text-2xl font-bold text-gray-900">Audit Log</h2>
+          <p className="text-sm text-gray-500">
+            Who exported what data, and when — required for DG-003 compliance.
+          </p>
+        </div>
+        {/* variant="secondary" for read-only/export action */}
+        <AuditLogExportButton
+          from={range.from}
+          to={range.to}
+          userId={userId}
+          action={action}
+        />
+      </div>
+
+      <AuditLogFilters
+        users={users}
+        from={range.from}
+        to={range.to}
+        userId={userId}
+        action={action}
+        onDateRangeChange={({ from, to }) => setCustomRange(from, to)}
+        onUserChange={setUserId}
+        onActionChange={setAction}
+        onClear={handleClearFilters}
+      />
+
+      {forbidden ? (
+        <div className="flex flex-col items-center gap-2 rounded-lg border border-gray-200 bg-white p-10 text-center">
+          <Shield className="h-8 w-8 text-gray-300" />
+          <p className="text-sm font-medium text-gray-900">
+            Admin access required
+          </p>
+          <p className="text-sm text-gray-500">
+            Only admins can view the audit log. See{" "}
+            <a
+              href="https://help.example.com/errors/AUTH_002"
+              className="text-brand-600 hover:underline"
+            >
+              AUTH_002
+            </a>{" "}
+            for details.
+          </p>
+        </div>
+      ) : errorMessage ? (
+        <div className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700">
+          {errorMessage}
+        </div>
+      ) : loading ? (
+        <AuditLogSkeleton />
+      ) : (
+        <>
+          <AuditLogTable entries={entries} />
+          {hasMore && (
+            <div className="flex justify-center">
+              <Button
+                variant="secondary"
+                onClick={handleLoadMore}
+                disabled={loadingMore}
+              >
+                {loadingMore ? "Loading..." : "Load more"}
+              </Button>
+            </div>
+          )}
+        </>
+      )}
+    </div>
+  );
+}
