+"use client";
+
+import { Label } from "@/components/ui/label";
+import { Select } from "@/components/ui/select";
+import { Button } from "@/components/ui/button";
+import { DateRangePicker } from "@/components/ui/date-range-picker";
+
+export interface AuditLogUserOption {
+  id: string;
+  name: string;
+}
+
+/** Known audit log action types. Kept in sync with the actions recorded by withAuditLog. */
+export const AUDIT_LOG_ACTIONS = [
+  { value: "export_analytics", label: "Exported analytics" },
+  { value: "export_audit_log", label: "Exported audit log" },
+] as const;
+
+interface AuditLogFiltersProps {
+  users: AuditLogUserOption[];
+  from: Date;
+  to: Date;
+  userId: string;
+  action: string;
+  onDateRangeChange: (range: { from: Date; to: Date }) => void;
+  onUserChange: (userId: string) => void;
+  onActionChange: (action: string) => void;
+  onClear: () => void;
+}
+
+/**
+ * Filter bar for the audit log viewer — date range, user, and action type.
+ *
+ * Uses read-only `variant="secondary"` actions throughout since filtering
+ * doesn't mutate data (see Button component conventions).
+ */
+export function AuditLogFilters({
+  users,
+  from,
+  to,
+  userId,
+  action,
+  onDateRangeChange,
+  onUserChange,
+  onActionChange,
+  onClear,
+}: AuditLogFiltersProps) {
+  const hasActiveFilters = Boolean(userId) || Boolean(action);
+
+  return (
+    <div className="flex flex-wrap items-end gap-3">
+      <div className="space-y-1">
+        <Label htmlFor="audit-date-range">Date range</Label>
+        <DateRangePicker
+          from={from}
+          to={to}
+          onSelect={onDateRangeChange}
+          className="w-64"
+        />
+      </div>
+
+      <div className="space-y-1">
+        <Label htmlFor="audit-user-filter">User</Label>
+        <Select
+          id="audit-user-filter"
+          value={userId}
+          onChange={(e) => onUserChange(e.target.value)}
+          className="w-48"
