+import { Badge } from "@/components/ui/badge";
+import { formatDate } from "@/lib/utils";
+import { getAuditLogStatus, type AuditLogEntry } from "@/types/audit-log";
+
+interface AuditLogTableProps {
+  entries: AuditLogEntry[];
+}
+
+const statusVariant = {
+  success: "success" as const,
+  error: "error" as const,
+  unknown: "neutral" as const,
+};
+
+const ACTION_LABELS: Record<string, string> = {
+  export_analytics: "Exported analytics",
+  export_audit_log: "Exported audit log",
+};
+
+function formatAction(action: string): string {
+  return ACTION_LABELS[action] ?? action.replace(/_/g, " ");
+}
+
+function initials(name: string): string {
+  return name
+    .split(" ")
+    .map((n) => n[0])
+    .join("")
+    .slice(0, 2)
+    .toUpperCase();
+}
+
+/**
+ * Table of audit log entries — who exported what data and when.
+ */
+export function AuditLogTable({ entries }: AuditLogTableProps) {
+  if (entries.length === 0) {
+    return (
+      <div className="rounded-lg border border-gray-200 bg-white p-8 text-center">
+        <p className="text-sm text-gray-500">
+          No audit log entries match the current filters.
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <div className="overflow-hidden rounded-lg border border-gray-200 bg-white">
+      <table className="w-full text-sm">
+        <thead>
+          <tr className="border-b border-gray-200 bg-gray-50 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+            <th className="px-4 py-3">User</th>
+            <th className="px-4 py-3">Action</th>
+            <th className="px-4 py-3">Resource</th>
+            <th className="px-4 py-3">Date</th>
+            <th className="px-4 py-3">Status</th>
+          </tr>
+        </thead>
+        <tbody className="divide-y divide-gray-100">
+          {entries.map((entry) => {
+            const status = getAuditLogStatus(entry);
+            return (
+              <tr key={entry.id} className="hover:bg-gray-50">
+                <td className="px-4 py-3">
+                  <div className="flex items-center gap-2">
+                    <div className="flex h-6 w-6 items-center justify-center rounded-full bg-gray-100 text-[10px] font-medium text-gray-600">
+                      {initials(entry.userName)}
+                    </div>
+                    <div>
+                      <p className="font-medium text-gray-900">{entry.userName}</p>
+                      <p className="text-xs text-gray-500">{entry.userEmail}</p>
+                    </div>
+                  </div>
+                </td>
+                <td className="px-4 py-3 capitalize text-gray-700">
+                  {formatAction(entry.action)}
+                </td>
+                <td className="px-4 py-3 text-gray-700">
+                  {entry.resourceType}
+                  {entry.resourceId ? ` · ${entry.resourceId}` : ""}
+                </td>
+                <td className="px-4 py-3 text-gray-500">
+                  {formatDate(entry.createdAt)}
+                </td>
+                <td className="px-4 py-3">
+                  <Badge variant={statusVariant[status]}>{status}</Badge>
+                </td>
+              </tr>
+            );
+          })}
+        </tbody>
+      </table>
+    </div>
+  );
+}
