+import { z } from "zod";
+
+/**
+ * Query filters for GET /api/audit-log — mirrors the analytics query
+ * validator pattern (src/lib/validators/analytics.ts).
+ */
+export const auditLogQuerySchema = z.object({
+  userId: z.string().optional(),
+  action: z.string().optional(),
+  startDate: z.coerce.date().optional(),
+  endDate: z.coerce.date().optional(),
+});
+
+/**
+ * Body for POST /api/audit-log/export.
+ *
+ * NOTE: exporting the audit log itself still counts as a data export under
+ * DG-003 and MUST be wrapped with withAuditLog — see
+ * src/app/api/audit-log/export/route.ts.
+ */
+export const auditLogExportSchema = z.object({
+  format: z.enum(["csv", "json"]).default("csv"),
+  startDate: z.coerce.date().optional(),
+  endDate: z.coerce.date().optional(),
+  userId: z.string().optional(),
+  action: z.string().optional(),
+});
+
+export type AuditLogQuery = z.infer<typeof auditLogQuerySchema>;
+export type AuditLogExportInput = z.infer<typeof auditLogExportSchema>;
