+/**
+ * Audit log types shared between the API and the admin viewer UI.
+ */
+
+export interface AuditLogEntry {
+  id: string;
+  userId: string;
+  userName: string;
+  userEmail: string;
+  action: string;
+  resourceType: string;
+  resourceId: string | null;
+  metadata: Record<string, unknown> | null;
+  ipAddress: string | null;
+  createdAt: string;
+}
+
+/** Status derived from the `metadata.status` field recorded by withAuditLog. */
+export type AuditLogStatus = "success" | "error" | "unknown";
+
+export function getAuditLogStatus(entry: AuditLogEntry): AuditLogStatus {
+  const status = entry.metadata?.status;
+  if (status === "success" || status === "error") {
+    return status;
+  }
+  return "unknown";
+}

