new file mode 100644
index 0000000..5bdef69
--- /dev/null
+++ b/src/app/api/analytics/export/preview/route.ts
@@ -0,0 +1,68 @@
+import { NextRequest } from "next/server";
+import { db } from "@/lib/db";
+import { analyticsEvents } from "@/lib/db/schema";
+import { eq, and, gte, lte, count } from "drizzle-orm";
+import { withAuth } from "@/lib/auth/with-auth";
+import { exportPreviewSchema } from "@/lib/validators/analytics";
+import { errorResponse } from "@/lib/errors";
+import { jsonResponse } from "@/lib/api/response";
+
+// Keep in sync with the row limit enforced by POST /api/analytics/export.
+const EXPORT_ROW_LIMIT = 10000;
+
+/**
+ * GET /api/analytics/export/preview — count how many records an export
+ * with the given date range (and optional event types) would return,
+ * without reading out the rows themselves.
+ *
+ * Lets the export UI show "X records will be exported" before the user
+ * commits to downloading, and warn them if the range is too large.
+ *
+ * Not wrapped in `withAuditLog`: this endpoint only returns a count, it
+ * never reads out record data, so it is not a "data export" under
+ * policy DG-003. The actual download still goes through
+ * POST /api/analytics/export, which is audited.
+ */
+export const GET = withAuth(async (req, { user }) => {
+  const url = new URL(req.url);
+  const eventTypesParam = url.searchParams.get("eventTypes");
+
+  const parsed = exportPreviewSchema.safeParse({
+    startDate: url.searchParams.get("startDate") || undefined,
+    endDate: url.searchParams.get("endDate") || undefined,
+    eventTypes: eventTypesParam
+      ? eventTypesParam.split(",").filter(Boolean)
+      : undefined,
+  });
+
+  if (!parsed.success) {
+    return errorResponse("VAL_001", 400, parsed.error.issues[0].message);
+  }
+
+  const { startDate, endDate, eventTypes } = parsed.data;
+
+  const conditions = [];
+
+  if (user.teamId) {
+    conditions.push(eq(analyticsEvents.teamId, user.teamId));
+  }
+  conditions.push(gte(analyticsEvents.createdAt, startDate));
+  conditions.push(lte(analyticsEvents.createdAt, endDate));
+
+  if (eventTypes && eventTypes.length > 0) {
+    // Mirrors the filtering in POST /api/analytics/export so the
+    // previewed count matches what the export will actually return.
+    conditions.push(eq(analyticsEvents.eventType, eventTypes[0]));
+  }
+
+  const [{ total }] = await db
+    .select({ total: count() })
+    .from(analyticsEvents)
+    .where(and(...conditions));
+
+  return jsonResponse({
+    count: total,
+    limit: EXPORT_ROW_LIMIT,
+    exceedsLimit: total > EXPORT_ROW_LIMIT,
+  });
+});
