+
+describe("ExportButton", () => {
+  const startDate = new Date("2026-01-01T00:00:00.000Z");
+  const endDate = new Date("2026-01-31T00:00:00.000Z");
+
+  beforeEach(() => {
+    vi.restoreAllMocks();
+    global.URL.createObjectURL = vi.fn(() => "blob:mock-url");
+    global.URL.revokeObjectURL = vi.fn();
+  });
+
+  afterEach(() => {
+    vi.unstubAllGlobals();
+  });
+
+  it("should render an Export trigger button next to filters", () => {
+    render(<ExportButton startDate={startDate} endDate={endDate} />);
+    expect(screen.getByRole("button", { name: /export/i })).toBeInTheDocument();
+  });
+
+  it("should fetch and show a record count preview when opened", async () => {
+    const fetchMock = vi.fn().mockResolvedValue({
+      ok: true,
+      json: async () => ({ count: 42, limit: 10000, exceedsLimit: false }),
+    });
+    vi.stubGlobal("fetch", fetchMock);
+
+    render(<ExportButton startDate={startDate} endDate={endDate} />);
+    fireEvent.click(screen.getByRole("button", { name: /export/i }));
+
+    await waitFor(() => {
+      expect(screen.getByText(/42 records will be exported/i)).toBeInTheDocument();
+    });
+
+    expect(fetchMock).toHaveBeenCalledWith(
+      expect.stringContaining("/api/analytics/export/preview")
+    );
+  });
+
+  it("should disable download when the preview exceeds the row limit", async () => {
+    const fetchMock = vi.fn().mockResolvedValue({
+      ok: true,
+      json: async () => ({ count: 20000, limit: 10000, exceedsLimit: true }),
+    });
+    vi.stubGlobal("fetch", fetchMock);
+
+    render(<ExportButton startDate={startDate} endDate={endDate} />);
+    fireEvent.click(screen.getByRole("button", { name: /export/i }));
+
+    await waitFor(() => {
+      expect(screen.getByText(/exceeds the 10,000 row limit/i)).toBeInTheDocument();
+    });
+
+    expect(screen.getByRole("button", { name: /download csv/i })).toBeDisabled();
+  });
+
+  it("should download a CSV when confirmed", async () => {
+    const csvBlob = new Blob(["id,team_id\n1,team-1"], { type: "text/csv" });
+    const fetchMock = vi
+      .fn()
+      // preview request
+      .mockResolvedValueOnce({
+        ok: true,
+        json: async () => ({ count: 3, limit: 10000, exceedsLimit: false }),
+      })
+      // export request
+      .mockResolvedValueOnce({
+        ok: true,
+        blob: async () => csvBlob,
+      });
+    vi.stubGlobal("fetch", fetchMock);
+
+    render(<ExportButton startDate={startDate} endDate={endDate} />);
+    fireEvent.click(screen.getByRole("button", { name: /export/i }));
+
+    const downloadButton = await screen.findByRole("button", {
+      name: /download csv/i,
+    });
+    await waitFor(() => expect(downloadButton).not.toBeDisabled());
+
+    fireEvent.click(downloadButton);
+
+    await waitFor(() => {
+      expect(fetchMock).toHaveBeenCalledWith(
+        "/api/analytics/export",
+        expect.objectContaining({ method: "POST" })
+      );
+    });
+  });
+});
