+                  preview.exceedsLimit ? "text-red-600" : "text-gray-700"
+                }
+              >
+                {preview.count.toLocaleString()} record
+                {preview.count === 1 ? "" : "s"} will be exported
+                {preview.exceedsLimit &&
+                  ` — exceeds the ${preview.limit?.toLocaleString()} row limit, narrow your date range`}
+              </span>
+            )}
+          </div>
+
+          <div className="mt-3 flex justify-end gap-2">
+            <Button variant="ghost" size="sm" onClick={() => setIsOpen(false)}>
+              Cancel
+            </Button>
+            <Button
+              variant="secondary"
+              size="sm"
+              onClick={handleExport}
+              disabled={
+                isExporting ||
+                preview.status === "loading" ||
+                preview.exceedsLimit ||
+                preview.count === 0
+              }
+            >
+              {isExporting ? "Downloading..." : "Download CSV"}
+            </Button>
+          </div>
+        </div>
+      )}
+    </div>
   );
 }
