diff --git a/src/app/audit/page.tsx b/src/app/audit/page.tsx
new file mode 100644
index 0000000..e2d578f
--- /dev/null
+++ b/src/app/audit/page.tsx
@@ -0,0 +1,177 @@
+"use client";
+
+import { useCallback, useEffect, useState } from "react";
+import { ShieldAlert } from "lucide-react";
+import { AuditLogFilters } from "@/components/audit/audit-log-filters";
+import { AuditLogTable } from "@/components/audit/audit-log-table";
+import { AuditLogExportButton } from "@/components/audit/audit-log-export-button";
+import { useDateRange } from "@/hooks/use-date-range";
+import { useToast } from "@/hooks/use-toast";
+import type { AuditLogEntry } from "@/types/audit";
+import type { User } from "@/types/user";
+
+interface AuditLogPage {
+  data: AuditLogEntry[];
+  nextCursor: string | null;
+  hasMore: boolean;
+}
+
+function buildQuery(params: Record<string, string | undefined>) {
+  const query = new URLSearchParams();
+  for (const [key, value] of Object.entries(params)) {
+    if (value) query.set(key, value);
+  }
+  return query.toString();
+}
+
+export default function AuditLogPage() {
+  const { range, setCustomRange } = useDateRange("30d");
+  const [userId, setUserId] = useState("");
+  const [action, setAction] = useState("");
+
+  const [users, setUsers] = useState<Pick<User, "id" | "name" | "email">[]>(
+    []
+  );
+  const [entries, setEntries] = useState<AuditLogEntry[]>([]);
+  const [cursor, setCursor] = useState<string | null>(null);
+  const [hasMore, setHasMore] = useState(false);
+  const [isLoading, setIsLoading] = useState(true);
+  const [isLoadingMore, setIsLoadingMore] = useState(false);
+  const [forbidden, setForbidden] = useState(false);
+
+  const toast = useToast();
+
+  const fetchEntries = useCallback(
+    async (nextCursor: string | null) => {
+      const query = buildQuery({
+        userId: userId || undefined,
+        action: action || undefined,
+        startDate: range.from.toISOString(),
+        endDate: range.to.toISOString(),
+        cursor: nextCursor || undefined,
+        limit: "20",
+      });
+
+      const response = await fetch(`/api/audit-logs?${query}`);
+
+      if (response.status === 403) {
+        setForbidden(true);
+        return null;
+      }
+
+      if (!response.ok) {
+        const error = await response.json();
+        toast.error(
+          error.help
+            ? `Failed to load audit log. See ${error.help}`
+            : "Failed to load audit log."
+        );
+        return null;
+      }
+
+      setForbidden(false);
+      return (await response.json()) as AuditLogPage;
+    },
+    [userId, action, range, toast]
+  );
+
+  // Reload from the start whenever a filter changes.
+  useEffect(() => {
+    let cancelled = false;
+    setIsLoading(true);
+
+    fetchEntries(null).then((page) => {
+      if (cancelled || !page) {
+        if (!cancelled) setIsLoading(false);
+        return;
+      }
+      setEntries(page.data);
+      setCursor(page.nextCursor);
+      setHasMore(page.hasMore);
+      setIsLoading(false);
+    });
+
+    return () => {
+      cancelled = true;
+    };
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [userId, action, range.from.getTime(), range.to.getTime()]);
+
+  // Load the list of users once, for the user filter dropdown.
+  useEffect(() => {
+    fetch("/api/users?limit=100")
+      .then((res) => (res.ok ? res.json() : null))
+      .then((page) => {
+        if (page?.data) setUsers(page.data);
+      })
+      .catch(() => {
+        // Non-fatal — the user filter just stays empty.
+      });
+  }, []);
+
+  const handleLoadMore = async () => {
+    setIsLoadingMore(true);
+    const page = await fetchEntries(cursor);
+    if (page) {
+      setEntries((prev) => [...prev, ...page.data]);
+      setCursor(page.nextCursor);
+      setHasMore(page.hasMore);
+    }
+    setIsLoadingMore(false);
+  };
+
+  if (forbidden) {
+    return (
+      <div className="flex flex-col items-center justify-center gap-3 rounded-lg border border-dashed border-gray-300 py-24 text-center">
+        <ShieldAlert className="h-8 w-8 text-gray-400" />
+        <p className="text-sm font-medium text-gray-900">
+          Admins only
+        </p>
+        <p className="max-w-sm text-sm text-gray-500">
+          The audit log is restricted to admin accounts. Ask a team admin if
+          you need access.
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <div className="space-y-6">
+      <div className="flex items-center justify-between">
+        <div>
+          <h2 className="text-2xl font-bold text-gray-900">Audit Log</h2>
+          <p className="text-sm text-gray-500">
+            Who exported what data, and when — required for DG-003
+            compliance.
+          </p>
+        </div>
+        <AuditLogExportButton
+          startDate={range.from}
+          endDate={range.to}
+          userId={userId}
+          action={action}
+        />
+      </div>
+
+      <AuditLogFilters
+        from={range.from}
+        to={range.to}
+        onDateRangeChange={({ from, to }) => setCustomRange(from, to)}
+        userId={userId}
+        onUserIdChange={setUserId}
+        users={users}
+        action={action}
+        onActionChange={setAction}
+        disabled={isLoading}
+      />
+
+      <AuditLogTable
+        entries={entries}
+        isLoading={isLoading}
+        isLoadingMore={isLoadingMore}
+        hasMore={hasMore}
+        onLoadMore={handleLoadMore}
+      />
+    </div>
+  );
+}
