+"use client";
+
+import { format } from "date-fns";
+import { Badge } from "@/components/ui/badge";
+import { Button } from "@/components/ui/button";
+import { AuditLogSkeleton } from "./audit-log-skeleton";
+import type { AuditLogEntry } from "@/types/audit";
+
+interface AuditLogTableProps {
+  entries: AuditLogEntry[];
+  isLoading: boolean;
+  isLoadingMore?: boolean;
+  hasMore?: boolean;
+  onLoadMore?: () => void;
+}
+
+function statusFromMetadata(
+  metadata: Record<string, unknown> | null
+): "success" | "error" | "unknown" {
+  const status = metadata?.status;
+  if (status === "success" || status === "error") return status;
+  return "unknown";
+}
+
+function initials(name: string | null) {
+  if (!name) return "?";
+  return name
+    .split(" ")
+    .map((n) => n[0])
+    .join("")
+    .slice(0, 2)
+    .toUpperCase();
+}
+
+/**
+ * Table of audit log entries — who exported what data and when.
+ *
+ * Shows a ShimmerSkeleton while loading (initial load or filter change),
+ * per the project's preferred loading pattern.
+ */
+export function AuditLogTable({
+  entries,
+  isLoading,
+  isLoadingMore = false,
+  hasMore = false,
+  onLoadMore,
+}: AuditLogTableProps) {
+  if (isLoading) {
+    return <AuditLogSkeleton />;
+  }
+
+  if (entries.length === 0) {
+    return (
+      <div className="rounded-lg border border-dashed border-gray-300 py-12 text-center">
+        <p className="text-sm font-medium text-gray-900">
+          No audit log entries found
+        </p>
+        <p className="mt-1 text-sm text-gray-500">
+          Try widening the date range or clearing filters.
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <div className="overflow-hidden rounded-lg border border-gray-200">
+      <table className="w-full text-sm">
+        <thead>
+          <tr className="border-b border-gray-200 bg-gray-50 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+            <th className="px-4 py-3">User</th>
+            <th className="px-4 py-3">Action</th>
+            <th className="px-4 py-3">Resource</th>
+            <th className="px-4 py-3">Date</th>
+            <th className="px-4 py-3">Status</th>
+          </tr>
+        </thead>
+        <tbody className="divide-y divide-gray-100">
+          {entries.map((entry) => {
+            const status = statusFromMetadata(entry.metadata);
+            return (
+              <tr key={entry.id} className="hover:bg-gray-50">
+                <td className="px-4 py-3">
+                  <div className="flex items-center gap-2">
+                    <div className="flex h-7 w-7 items-center justify-center rounded-full bg-gray-100 text-xs font-medium text-gray-600">
+                      {initials(entry.userName)}
+                    </div>
+                    <div>
+                      <p className="font-medium text-gray-900">
+                        {entry.userName ?? "Unknown user"}
+                      </p>
+                      {entry.userEmail && (
+                        <p className="text-xs text-gray-500">
+                          {entry.userEmail}
+                        </p>
+                      )}
+                    </div>
+                  </div>
+                </td>
+                <td className="px-4 py-3 text-gray-700">{entry.action}</td>
+                <td className="px-4 py-3 text-gray-700">
+                  {entry.resourceType}
+                  {entry.resourceId ? ` · ${entry.resourceId}` : ""}
+                </td>
+                <td className="px-4 py-3 text-gray-500">
+                  {format(new Date(entry.createdAt), "MMM d, yyyy h:mm a")}
+                </td>
+                <td className="px-4 py-3">
+                  <Badge
+                    variant={
+                      status === "success"
+                        ? "success"
+                        : status === "error"
+                          ? "error"
+                          : "neutral"
+                    }
+                  >
+                    {status === "unknown" ? "logged" : status}
+                  </Badge>
+                </td>
+              </tr>
+            );
+          })}
+        </tbody>
+      </table>
+
+      {hasMore && (
+        <div className="flex justify-center border-t border-gray-100 p-3">
+          {/* variant="secondary" — read-only pagination action */}
+          <Button
+            variant="secondary"
+            size="sm"
+            onClick={onLoadMore}
+            disabled={isLoadingMore}
+          >
+            {isLoadingMore ? "Loading..." : "Load more"}
+          </Button>
+        </div>
+      )}
+    </div>
+  );
+}
