+import { describe, it, expect } from "vitest";
+import { auditLogQuerySchema, exportAuditLogSchema } from "./audit-log";
+
+describe("audit-log validators", () => {
+  describe("auditLogQuerySchema", () => {
+    it("should accept an empty query (no filters)", () => {
+      const result = auditLogQuerySchema.safeParse({});
+      expect(result.success).toBe(true);
+    });
+
+    it("should accept userId and action filters", () => {
+      const result = auditLogQuerySchema.safeParse({
+        userId: "user-1",
+        action: "export_analytics",
+      });
+      expect(result.success).toBe(true);
+    });
+
+    it("should coerce date strings for startDate/endDate", () => {
+      const result = auditLogQuerySchema.safeParse({
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+      });
+      expect(result.success).toBe(true);
+      if (result.success) {
+        expect(result.data.startDate).toBeInstanceOf(Date);
+        expect(result.data.endDate).toBeInstanceOf(Date);
+      }
+    });
+
+    it("should reject an invalid date", () => {
+      const result = auditLogQuerySchema.safeParse({
+        startDate: "not-a-date",
+      });
+      expect(result.success).toBe(false);
+    });
+  });
+
+  describe("exportAuditLogSchema", () => {
+    it("should default format to csv", () => {
+      const result = exportAuditLogSchema.parse({});
+      expect(result.format).toBe("csv");
+    });
+
+    it("should accept json format", () => {
+      const result = exportAuditLogSchema.safeParse({ format: "json" });
+      expect(result.success).toBe(true);
+    });
+
+    it("should reject an unsupported format", () => {
+      const result = exportAuditLogSchema.safeParse({ format: "xml" });
+      expect(result.success).toBe(false);
+    });
+
+    it("should carry through filters alongside format", () => {
+      const result = exportAuditLogSchema.safeParse({
+        format: "csv",
+        userId: "user-1",
+        action: "export_audit_log",
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+      });
+      expect(result.success).toBe(true);
+    });
+  });
+});
