+  MAX_EXPORT_RECORDS,
+} from "./analytics";
+
+describe("analytics validators", () => {
+  describe("analyticsQuerySchema", () => {
+    it("should accept an empty object (all fields optional)", () => {
+      const result = analyticsQuerySchema.safeParse({});
+      expect(result.success).toBe(true);
+    });
+
+    it("should coerce date strings", () => {
+      const result = analyticsQuerySchema.parse({
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+      });
+      expect(result.startDate).toBeInstanceOf(Date);
+      expect(result.endDate).toBeInstanceOf(Date);
+    });
+  });
+
+  describe("exportAnalyticsSchema", () => {
+    it("should require startDate and endDate", () => {
+      const result = exportAnalyticsSchema.safeParse({});
+      expect(result.success).toBe(false);
+    });
+
+    it("should default format to csv", () => {
+      const result = exportAnalyticsSchema.parse({
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+      });
+      expect(result.format).toBe("csv");
+    });
+
+    it("should accept json format", () => {
+      const result = exportAnalyticsSchema.safeParse({
+        format: "json",
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+      });
+      expect(result.success).toBe(true);
+    });
+
+    it("should reject an invalid format", () => {
+      const result = exportAnalyticsSchema.safeParse({
+        format: "xml",
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+      });
+      expect(result.success).toBe(false);
+    });
+  });
+
+  describe("exportPreviewSchema", () => {
+    it("should require startDate and endDate", () => {
+      const result = exportPreviewSchema.safeParse({});
+      expect(result.success).toBe(false);
+    });
+
+    it("should accept a valid date range", () => {
+      const result = exportPreviewSchema.safeParse({
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+      });
+      expect(result.success).toBe(true);
+    });
+  });
+
+  describe("MAX_EXPORT_RECORDS", () => {
+    it("should be a positive number", () => {
+      expect(MAX_EXPORT_RECORDS).toBeGreaterThan(0);
