+  const [nextCursor, setNextCursor] = useState<string | null>(null);
+  const [hasMore, setHasMore] = useState(false);
+  const [loading, setLoading] = useState(true);
+  const [loadingMore, setLoadingMore] = useState(false);
+  const [forbidden, setForbidden] = useState(false);
+  const toast = useToast();
+
+  // Populate the user filter from the team roster (not just users seen on
+  // the current page), so filtering works even before any matching entries
+  // have loaded.
+  useEffect(() => {
+    let cancelled = false;
+    fetch("/api/users?limit=100")
+      .then((res) => (res.ok ? res.json() : null))
+      .then((page: PaginatedResponse<{ id: string; name: string }> | null) => {
+        if (!cancelled && page) {
+          setUserOptions(page.data.map((u) => ({ id: u.id, name: u.name })));
+        }
+      })
+      .catch(() => undefined);
+    return () => {
+      cancelled = true;
+    };
+  }, []);
+
+  const actionOptions = useMemo(() => {
+    const seen = new Set(DEFAULT_ACTIONS);
+    for (const entry of entries) seen.add(entry.action);
+    return Array.from(seen);
+  }, [entries]);
+
+  const fetchPage = useCallback(
+    async (cursor?: string): Promise<PaginatedResponse<AuditLogEntry> | null> => {
+      const params = new URLSearchParams();
+      params.set("startDate", range.from.toISOString());
+      params.set("endDate", range.to.toISOString());
+      if (userId) params.set("userId", userId);
+      if (action) params.set("action", action);
+      if (cursor) params.set("cursor", cursor);
+
+      const response = await fetch(`/api/audit-log?${params.toString()}`);
+
+      if (response.status === 403) {
+        setForbidden(true);
+        return null;
+      }
+
+      if (!response.ok) {
+        const error = await response.json().catch(() => null);
+        toast.error(
+          error?.help
+            ? `Failed to load audit log. See ${error.help}`
+            : "Failed to load audit log."
+        );
+        return null;
+      }
+
+      return (await response.json()) as PaginatedResponse<AuditLogEntry>;
+    },
+    [range, userId, action, toast]
+  );
+
+  useEffect(() => {
+    let cancelled = false;
+    setLoading(true);
+    setForbidden(false);
+
+    fetchPage()
+      .then((page) => {
+        if (cancelled || !page) return;
+        setEntries(page.data);
+        setNextCursor(page.nextCursor);
+        setHasMore(page.hasMore);
+      })
+      .finally(() => {
+        if (!cancelled) setLoading(false);
+      });
+
+    return () => {
+      cancelled = true;
+    };
+  }, [fetchPage]);
+
+  const handleLoadMore = async () => {
+    if (!nextCursor) return;
+    setLoadingMore(true);
+    const page = await fetchPage(nextCursor);
+    if (page) {
+      setEntries((prev) => [...prev, ...page.data]);
+      setNextCursor(page.nextCursor);
+      setHasMore(page.hasMore);
+    }
+    setLoadingMore(false);
+  };
+
+  if (forbidden) {
+    return (
+      <div className="flex h-64 flex-col items-center justify-center gap-2 rounded-lg border border-gray-200 bg-white text-center">
+        <Shield className="h-8 w-8 text-gray-300" />
+        <p className="text-sm font-medium text-gray-900">Admins only</p>
+        <p className="text-sm text-gray-500">
+          You need admin access to view the audit log.
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <div className="space-y-6">
+      <div className="flex items-center justify-between">
+        <div>
+          <h2 className="text-2xl font-bold text-gray-900">Audit Log</h2>
+          <p className="text-sm text-gray-500">
+            Who exported what data, and when
+          </p>
+        </div>
+        {/* variant="secondary" for read-only/export action — see export-button convention */}
+        <AuditLogExportButton
+          startDate={range.from}
+          endDate={range.to}
+          userId={userId || undefined}
+          action={action || undefined}
+        />
+      </div>
+
+      <AuditLogFilters
+        value={{ from: range.from, to: range.to, userId, action }}
+        users={userOptions}
+        actions={actionOptions}
+        onDateRangeChange={({ from, to }) => setCustomRange(from, to)}
+        onUserChange={setUserId}
+        onActionChange={setAction}
+      />
+
+      {loading ? (
+        <AuditLogTableSkeleton />
+      ) : (
+        <>
+          <AuditLogTable entries={entries} />
+          {hasMore && (
+            <div className="flex justify-center">
+              <Button
+                variant="secondary"
+                onClick={handleLoadMore}
+                disabled={loadingMore}
+              >
+                {loadingMore ? "Loading..." : "Load more"}
+              </Button>
+            </div>
+          )}
+        </>
+      )}
+    </div>
+  );
+}
