+"use client";
+
+import { Select } from "@/components/ui/select";
+import { DateRangePicker } from "@/components/ui/date-range-picker";
+
+export interface AuditLogFiltersValue {
+  from: Date;
+  to: Date;
+  userId: string;
+  action: string;
+}
+
+interface AuditLogUserOption {
+  id: string;
+  name: string;
+}
+
+interface AuditLogFiltersProps {
+  value: AuditLogFiltersValue;
+  users: AuditLogUserOption[];
+  actions: string[];
+  onDateRangeChange: (range: { from: Date; to: Date }) => void;
+  onUserChange: (userId: string) => void;
+  onActionChange: (action: string) => void;
+}
+
+/**
+ * Filter controls for the audit log viewer: date range, user, and action type.
+ *
+ * Uses DateRangePicker (the preferred `from`/`to` date range component) and
+ * Select for the user/action filters, matching existing design system
+ * conventions.
+ */
+export function AuditLogFilters({
+  value,
+  users,
+  actions,
+  onDateRangeChange,
+  onUserChange,
+  onActionChange,
+}: AuditLogFiltersProps) {
+  return (
+    <div className="flex flex-wrap items-center gap-3">
+      <DateRangePicker
+        from={value.from}
+        to={value.to}
+        onSelect={onDateRangeChange}
+        className="w-72"
+      />
+
+      <Select
+        aria-label="Filter by user"
+        value={value.userId}
+        onChange={(e) => onUserChange(e.target.value)}
+        className="w-48"
+      >
+        <option value="">All users</option>
+        {users.map((u) => (
+          <option key={u.id} value={u.id}>
+            {u.name}
+          </option>
+        ))}
+      </Select>
+
+      <Select
+        aria-label="Filter by action"
+        value={value.action}
+        onChange={(e) => onActionChange(e.target.value)}
+        className="w-48"
+      >
+        <option value="">All actions</option>
+        {actions.map((a) => (
+          <option key={a} value={a}>
+            {a}
+          </option>
+        ))}
+      </Select>
+    </div>
+  );
+}
