+"use client";
+
+import { Badge } from "@/components/ui/badge";
+import { formatDate } from "@/lib/utils";
+import type { AuditLogEntry } from "@/types/audit-log";
+
+interface AuditLogTableProps {
+  entries: AuditLogEntry[];
+}
+
+/**
+ * Table of audit log entries: who exported what data, and when.
+ *
+ * Status (success/error) comes from the `status` field recorded by
+ * `withAuditLog` in the entry's metadata (see src/lib/audit-log/index.ts).
+ */
+export function AuditLogTable({ entries }: AuditLogTableProps) {
+  if (entries.length === 0) {
+    return (
+      <div className="flex h-32 items-center justify-center rounded-lg border border-gray-200 bg-white text-sm text-gray-500">
+        No audit log entries match the selected filters.
+      </div>
+    );
+  }
+
+  return (
+    <div className="overflow-hidden rounded-lg border border-gray-200 bg-white">
+      <table className="w-full text-left text-sm">
+        <thead className="border-b border-gray-200 bg-gray-50">
+          <tr>
+            <th className="px-4 py-3 font-medium text-gray-500">User</th>
+            <th className="px-4 py-3 font-medium text-gray-500">Action</th>
+            <th className="px-4 py-3 font-medium text-gray-500">Resource</th>
+            <th className="px-4 py-3 font-medium text-gray-500">Status</th>
+            <th className="px-4 py-3 font-medium text-gray-500">IP Address</th>
+            <th className="px-4 py-3 font-medium text-gray-500">When</th>
+          </tr>
+        </thead>
+        <tbody className="divide-y divide-gray-100">
+          {entries.map((entry) => {
+            const status =
+              entry.metadata && typeof entry.metadata.status === "string"
+                ? entry.metadata.status
+                : null;
+
+            return (
+              <tr key={entry.id}>
+                <td className="px-4 py-3">
+                  <div className="font-medium text-gray-900">
+                    {entry.userName ?? "Unknown user"}
+                  </div>
+                  {entry.userEmail && (
+                    <div className="text-xs text-gray-500">{entry.userEmail}</div>
+                  )}
+                </td>
+                <td className="px-4 py-3 text-gray-700">{entry.action}</td>
+                <td className="px-4 py-3 text-gray-700">
+                  {entry.resourceType}
+                  {entry.resourceId ? ` / ${entry.resourceId}` : ""}
+                </td>
+                <td className="px-4 py-3">
+                  {status === "error" ? (
+                    <Badge variant="error">failed</Badge>
+                  ) : status === "success" ? (
+                    <Badge variant="success">success</Badge>
+                  ) : (
+                    <Badge variant="neutral">unknown</Badge>
+                  )}
+                </td>
+                <td className="px-4 py-3 text-gray-500">
+                  {entry.ipAddress ?? "—"}
+                </td>
+                <td className="px-4 py-3 text-gray-500">
+                  {formatDate(entry.createdAt)}
+                </td>
+              </tr>
+            );
+          })}
+        </tbody>
+      </table>
+    </div>
+  );
+}
