+import { describe, it, expect } from "vitest";
+import { auditLogQuerySchema, exportAuditLogSchema } from "./audit-log";
+
+describe("audit-log validators", () => {
+  describe("auditLogQuerySchema", () => {
+    it("should accept an empty object (all filters optional)", () => {
+      const result = auditLogQuerySchema.safeParse({});
+      expect(result.success).toBe(true);
+    });
+
+    it("should accept valid filters", () => {
+      const result = auditLogQuerySchema.safeParse({
+        userId: "user-1",
+        action: "export_analytics",
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+      });
+      expect(result.success).toBe(true);
+    });
+
+    it("should coerce date strings to Date objects", () => {
+      const result = auditLogQuerySchema.parse({ startDate: "2024-01-01" });
+      expect(result.startDate).toBeInstanceOf(Date);
+    });
+
+    it("should reject invalid dates", () => {
+      const result = auditLogQuerySchema.safeParse({ startDate: "not-a-date" });
+      expect(result.success).toBe(false);
+    });
+  });
+
+  describe("exportAuditLogSchema", () => {
+    it("should require startDate and endDate", () => {
+      const result = exportAuditLogSchema.safeParse({});
+      expect(result.success).toBe(false);
+    });
+
+    it("should default format to csv", () => {
+      const result = exportAuditLogSchema.parse({
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+      });
+      expect(result.format).toBe("csv");
+    });
+
+    it("should accept json format", () => {
+      const result = exportAuditLogSchema.safeParse({
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+        format: "json",
+      });
+      expect(result.success).toBe(true);
+    });
+
+    it("should reject an unsupported format", () => {
+      const result = exportAuditLogSchema.safeParse({
+        startDate: "2024-01-01",
+        endDate: "2024-01-31",
+        format: "xml",
+      });
+      expect(result.success).toBe(false);
+    });
+
+    it("should accept optional userId and action filters", () => {
+      const result = exportAuditLogSchema.safeParse({
+        startDate: "2024-01-01",
