+import { NextRequest } from "next/server";
+import { db } from "@/lib/db";
+import { auditLogs, users } from "@/lib/db/schema";
+import { eq, and, gte, lte, lt, desc } from "drizzle-orm";
+import { withAuth, requireRole } from "@/lib/auth/with-auth";
+import { auditLogQuerySchema } from "@/lib/validators/audit-log";
+import {
+  paginationSchema,
+  decodeCursor,
+  buildCursorPage,
+} from "@/lib/api/pagination";
+import { errorResponse } from "@/lib/errors";
+import { jsonResponse } from "@/lib/api/response";
+
+/**
+ * GET /api/audit-log — list audit log entries with cursor pagination.
+ *
+ * Admin only. Supports filtering by userId, action, and date range.
+ * Joins the acting user's name/email so the UI can show "who" exported
+ * data without a second round trip.
+ *
+ * Uses cursor-based pagination per convention. Do NOT use offset/limit.
+ */
+export const GET = withAuth(async (req, { user }) => {
+  const roleCheck = requireRole(user, "admin");
+  if (roleCheck) return roleCheck;
+
+  const url = new URL(req.url);
+
+  const filters = auditLogQuerySchema.safeParse({
+    userId: url.searchParams.get("userId") || undefined,
+    action: url.searchParams.get("action") || undefined,
+    startDate: url.searchParams.get("startDate") || undefined,
+    endDate: url.searchParams.get("endDate") || undefined,
+  });
+
+  const pagination = paginationSchema.safeParse({
+    cursor: url.searchParams.get("cursor") || undefined,
+    limit: url.searchParams.get("limit") || 20,
+  });
+
+  if (!filters.success || !pagination.success) {
+    return errorResponse("VAL_001", 400);
+  }
+
+  const { userId, action, startDate, endDate } = filters.data;
+  const { cursor, limit } = pagination.data;
+
+  const conditions = [];
+
+  if (userId) {
+    conditions.push(eq(auditLogs.userId, userId));
+  }
+  if (action) {
+    conditions.push(eq(auditLogs.action, action));
+  }
+  if (startDate) {
+    conditions.push(gte(auditLogs.createdAt, startDate));
+  }
+  if (endDate) {
+    conditions.push(lte(auditLogs.createdAt, endDate));
+  }
+  if (cursor) {
+    try {
+      const decoded = decodeCursor(cursor);
+      conditions.push(lt(auditLogs.createdAt, decoded.createdAt));
+    } catch {
+      return errorResponse("VAL_002", 400);
+    }
+  }
+
+  const results = await db
+    .select({
+      id: auditLogs.id,
+      userId: auditLogs.userId,
+      userName: users.name,
+      userEmail: users.email,
+      action: auditLogs.action,
+      resourceType: auditLogs.resourceType,
+      resourceId: auditLogs.resourceId,
+      metadata: auditLogs.metadata,
+      ipAddress: auditLogs.ipAddress,
+      createdAt: auditLogs.createdAt,
+    })
+    .from(auditLogs)
+    .leftJoin(users, eq(auditLogs.userId, users.id))
+    .where(conditions.length > 0 ? and(...conditions) : undefined)
+    .orderBy(desc(auditLogs.createdAt))
+    .limit(limit + 1);
+
+  const page = buildCursorPage(
+    results.map((r) => ({
+      id: r.id,
+      userId: r.userId,
+      userName: r.userName,
+      userEmail: r.userEmail,
+      action: r.action,
+      resourceType: r.resourceType,
+      resourceId: r.resourceId,
+      metadata: r.metadata ? JSON.parse(r.metadata) : null,
+      ipAddress: r.ipAddress,
+      createdAt: r.createdAt,
+    })),
+    limit
+  );
+
+  return jsonResponse(page);
+});
