@@ -0,0 +1,188 @@
+"use client";
+
+import { useCallback, useEffect, useState } from "react";
+import { Button } from "@/components/ui/button";
+import { AuditLogTable } from "@/components/audit/audit-log-table";
+import { AuditLogFilters } from "@/components/audit/audit-log-filters";
+import { AuditLogExportButton } from "@/components/audit/audit-log-export-button";
+import { AuditLogTableSkeleton } from "@/components/audit/audit-log-skeleton";
+import { useDateRange } from "@/hooks/use-date-range";
+import { useToast } from "@/hooks/use-toast";
+import type { AuditLogEntry } from "@/types/audit-log";
+import type { ApiError, PaginatedResponse } from "@/types/api";
+
+export default function AuditLogPage() {
+  const { range, setCustomRange } = useDateRange("30d");
+  const [userId, setUserId] = useState("");
+  const [action, setAction] = useState("");
+
+  const [entries, setEntries] = useState<AuditLogEntry[]>([]);
+  const [cursor, setCursor] = useState<string | null>(null);
+  const [hasMore, setHasMore] = useState(false);
+  const [isLoading, setIsLoading] = useState(true);
+  const [isLoadingMore, setIsLoadingMore] = useState(false);
+  const [forbidden, setForbidden] = useState(false);
+  const [loadError, setLoadError] = useState<string | null>(null);
+
+  const toast = useToast();
+
+  const fetchEntries = useCallback(
+    async (nextCursor?: string | null) => {
+      const params = new URLSearchParams();
+      params.set("startDate", range.from.toISOString());
+      params.set("endDate", range.to.toISOString());
+      if (userId) params.set("userId", userId);
+      if (action) params.set("action", action);
+      if (nextCursor) params.set("cursor", nextCursor);
+
+      const response = await fetch(`/api/audit-log?${params.toString()}`);
+
+      if (response.status === 403) {
+        setForbidden(true);
+        return null;
+      }
+
+      if (!response.ok) {
+        const error: ApiError = await response.json();
+        throw new Error(
+          error.help ? `${error.error}. See ${error.help}` : error.error
+        );
+      }
+
+      return (await response.json()) as PaginatedResponse<AuditLogEntry>;
+    },
+    [range.from, range.to, userId, action]
+  );
+
+  useEffect(() => {
+    let cancelled = false;
+
+    async function load() {
+      setIsLoading(true);
+      setLoadError(null);
+      setForbidden(false);
+
+      try {
+        const page = await fetchEntries();
+        if (cancelled) return;
+        if (page) {
+          setEntries(page.data);
+          setCursor(page.nextCursor);
+          setHasMore(page.hasMore);
+        }
+      } catch (err) {
+        if (!cancelled) {
+          setLoadError(
+            err instanceof Error ? err.message : "Failed to load audit log"
+          );
+        }
+      } finally {
+        if (!cancelled) setIsLoading(false);
+      }
+    }
+
+    load();
+    return () => {
+      cancelled = true;
+    };
+  }, [fetchEntries]);
+
+  const handleLoadMore = async () => {
+    if (!cursor) return;
+    setIsLoadingMore(true);
+    try {
+      const page = await fetchEntries(cursor);
+      if (page) {
+        setEntries((prev) => [...prev, ...page.data]);
+        setCursor(page.nextCursor);
+        setHasMore(page.hasMore);
+      }
+    } catch (err) {
+      toast.error(
+        err instanceof Error ? err.message : "Failed to load more entries"
+      );
+    } finally {
+      setIsLoadingMore(false);
+    }
+  };
+
+  if (forbidden) {
+    return (
+      <div className="space-y-6">
+        <div>
+          <h2 className="text-2xl font-bold text-gray-900">Audit Log</h2>
+        </div>
+        <div className="rounded-lg border border-dashed border-gray-300 py-12 text-center">
+          <p className="text-sm font-medium text-gray-900">
+            Admins only
+          </p>
+          <p className="mt-1 text-sm text-gray-500">
+            You don&apos;t have permission to view the audit log. See{" "}
+            <a
+              href="https://help.example.com/errors/AUTH_002"
+              className="text-brand-600 underline"
+            >
+              https://help.example.com/errors/AUTH_002
+            </a>
+            .
+          </p>
+        </div>
+      </div>
+    );
+  }
+
+  return (
+    <div className="space-y-6">
+      <div className="flex flex-wrap items-center justify-between gap-3">
+        <div>
+          <h2 className="text-2xl font-bold text-gray-900">Audit Log</h2>
+          <p className="text-sm text-gray-500">
+            Who exported what data, and when.
+          </p>
+        </div>
+        <AuditLogExportButton
+          startDate={range.from}
+          endDate={range.to}
+          userId={userId}
+          action={action}
+        />
+      </div>
+
+      <AuditLogFilters
+        from={range.from}
+        to={range.to}
+        onDateRangeChange={({ from, to }) => setCustomRange(from, to)}
+        userId={userId}
+        onUserIdChange={setUserId}
+        action={action}
+        onActionChange={setAction}
+      />
+
+      {isLoading ? (
+        <AuditLogTableSkeleton />
+      ) : loadError ? (
+        <div className="rounded-lg border border-dashed border-red-200 bg-red-50 py-12 text-center">
+          <p className="text-sm font-medium text-red-700">
+            Couldn&apos;t load the audit log
+          </p>
+          <p className="mt-1 text-sm text-red-600">{loadError}</p>
+        </div>
+      ) : (
+        <>
+          <AuditLogTable entries={entries} />
+          {hasMore && (
+            <div className="flex justify-center">
+              <Button
+                variant="secondary"
+                onClick={handleLoadMore}
+                disabled={isLoadingMore}
+              >
+                {isLoadingMore ? "Loading..." : "Load more"}
+              </Button>
+            </div>
+          )}
+        </>
+      )}
+    </div>
+  );
+}
