+"use client";
+
+import { useEffect, useState } from "react";
+import { DateRangePicker } from "@/components/ui/date-range-picker";
+import { Select } from "@/components/ui/select";
+import { AUDIT_ACTIONS } from "@/types/audit-log";
+
+interface FilterUser {
+  id: string;
+  name: string;
+  email: string;
+}
+
+interface AuditLogFiltersProps {
+  from: Date;
+  to: Date;
+  onDateRangeChange: (range: { from: Date; to: Date }) => void;
+  userId: string;
+  onUserIdChange: (userId: string) => void;
+  action: string;
+  onActionChange: (action: string) => void;
+}
+
+/**
+ * Filter bar for the audit log viewer: date range, acting user, and
+ * action type. The user list is fetched from /api/users so admins can
+ * filter by a real teammate rather than typing a raw user ID.
+ */
+export function AuditLogFilters({
+  from,
+  to,
+  onDateRangeChange,
+  userId,
+  onUserIdChange,
+  action,
+  onActionChange,
+}: AuditLogFiltersProps) {
+  const [users, setUsers] = useState<FilterUser[]>([]);
+
+  useEffect(() => {
+    let cancelled = false;
+
+    async function loadUsers() {
+      try {
+        const response = await fetch("/api/users?limit=100");
+        if (!response.ok || cancelled) return;
+        const page = await response.json();
+        if (!cancelled) {
+          setUsers(page.data ?? []);
+        }
+      } catch {
+        // Non-fatal — the user filter just falls back to "All users".
+      }
+    }
+
+    loadUsers();
+    return () => {
+      cancelled = true;
+    };
+  }, []);
+
+  return (
+    <div className="flex flex-wrap items-center gap-3">
+      <DateRangePicker from={from} to={to} onSelect={onDateRangeChange} className="w-72" />
+
+      <Select
+        value={userId}
+        onChange={(e) => onUserIdChange(e.target.value)}
+        className="w-48"
+        aria-label="Filter by user"
+      >
+        <option value="">All users</option>
+        {users.map((u) => (
+          <option key={u.id} value={u.id}>
+            {u.name}
+          </option>
+        ))}
+      </Select>
+
+      <Select
+        value={action}
+        onChange={(e) => onActionChange(e.target.value)}
+        className="w-48"
+        aria-label="Filter by action type"
+      >
+        <option value="">All actions</option>
+        {AUDIT_ACTIONS.map((a) => (
+          <option key={a} value={a}>
+            {a
+              .split("_")
+              .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
+              .join(" ")}
+          </option>
+        ))}
+      </Select>
+    </div>
+  );
+}
