+import type { AuditLogEntry } from "@/types/audit-log";
+
+interface AuditLogTableProps {
+  entries: AuditLogEntry[];
+}
+
+function formatAction(action: string): string {
+  return action
+    .split("_")
+    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
+    .join(" ");
+}
+
+function getStatus(entry: AuditLogEntry): "success" | "error" | "unknown" {
+  const status = entry.metadata?.status;
+  if (status === "success" || status === "error") return status;
+  return "unknown";
+}
+
+export function AuditLogTable({ entries }: AuditLogTableProps) {
+  if (entries.length === 0) {
+    return (
+      <div className="rounded-lg border border-dashed border-gray-300 py-12 text-center">
+        <p className="text-sm font-medium text-gray-900">No audit log entries</p>
+        <p className="mt-1 text-sm text-gray-500">
+          Try widening the date range or clearing your filters.
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <div className="overflow-x-auto rounded-lg border border-gray-200">
+      <table className="w-full min-w-[720px] text-left text-sm">
+        <thead className="bg-gray-50 text-xs font-medium uppercase tracking-wide text-gray-500">
+          <tr>
+            <th className="px-4 py-3">User</th>
+            <th className="px-4 py-3">Action</th>
+            <th className="px-4 py-3">Resource</th>
+            <th className="px-4 py-3">Date</th>
+            <th className="px-4 py-3">Status</th>
+          </tr>
+        </thead>
