diff --git a/src/app/api/audit-log/export/route.ts b/src/app/api/audit-log/export/route.ts
new file mode 100644
index 0000000..e70e386
--- /dev/null
+++ b/src/app/api/audit-log/export/route.ts
@@ -0,0 +1,112 @@
+import { db } from "@/lib/db";
+import { auditLogs, users } from "@/lib/db/schema";
+import { eq, and, gte, lte, desc } from "drizzle-orm";
+import { withAuth, requireRole } from "@/lib/auth/with-auth";
+import { withAuditLog } from "@/lib/audit-log";
+import { exportAuditLogSchema } from "@/lib/validators/audit-log";
+import { errorResponse } from "@/lib/errors";
+
+/**
+ * POST /api/audit-log/export — export the audit log itself.
+ *
+ * Admin only. IMPORTANT: this endpoint also uses `withAuditLog` to comply
+ * with data governance policy DG-003 — exporting the audit log is itself
+ * a data export and MUST be audited, the same as any other export.
+ */
+export const POST = withAuth(async (req, { user }) => {
+  const roleCheck = requireRole(user, "admin");
+  if (roleCheck) return roleCheck;
+
+  const body = await req.json();
+  const parsed = exportAuditLogSchema.safeParse(body);
+
+  if (!parsed.success) {
+    return errorResponse("VAL_001", 400, parsed.error.issues[0].message);
+  }
+
+  const { format, startDate, endDate, userId, action } = parsed.data;
+
+  return withAuditLog("export_audit_log", user.id, req, async () => {
+    const conditions = [];
+
+    if (user.teamId) {
+      conditions.push(eq(users.teamId, user.teamId));
+    }
+    conditions.push(gte(auditLogs.createdAt, startDate));
+    conditions.push(lte(auditLogs.createdAt, endDate));
+
+    if (userId) {
+      conditions.push(eq(auditLogs.userId, userId));
+    }
+    if (action) {
+      conditions.push(eq(auditLogs.action, action));
+    }
+
+    const results = await db
+      .select({
+        id: auditLogs.id,
+        userId: auditLogs.userId,
+        userName: users.name,
+        userEmail: users.email,
+        action: auditLogs.action,
+        resourceType: auditLogs.resourceType,
+        resourceId: auditLogs.resourceId,
+        ipAddress: auditLogs.ipAddress,
+        createdAt: auditLogs.createdAt,
+      })
+      .from(auditLogs)
+      .innerJoin(users, eq(auditLogs.userId, users.id))
+      .where(and(...conditions))
+      .orderBy(desc(auditLogs.createdAt));
+
+    if (results.length > 10000) {
+      return errorResponse("EXPORT_002", 400);
+    }
+
+    if (format === "json") {
+      return Response.json(results, {
+        headers: {
+          "Content-Disposition": "attachment; filename=audit-log-export.json",
+        },
+      });
+    }
+
+    // CSV format
+    const headers = [
+      "id",
+      "user_name",
+      "user_email",
+      "action",
+      "resource_type",
+      "resource_id",
+      "ip_address",
+      "created_at",
+    ];
+    const csvRows = [
+      headers.join(","),
+      ...results.map((r) =>
+        [
+          r.id,
+          csvEscape(r.userName),
+          r.userEmail,
+          r.action,
+          r.resourceType,
+          r.resourceId || "",
+          r.ipAddress || "",
+          r.createdAt.toISOString(),
+        ].join(",")
+      ),
+    ];
+
+    return new Response(csvRows.join("\n"), {
+      headers: {
+        "Content-Type": "text/csv",
+        "Content-Disposition": "attachment; filename=audit-log-export.csv",
+      },
+    });
+  });
+});
+
+function csvEscape(value: string): string {
+  return /[",\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
+}
