+import { db } from "@/lib/db";
+import { auditLogs, users } from "@/lib/db/schema";
+import { eq, desc } from "drizzle-orm";
+import { withAuth, requireRole } from "@/lib/auth/with-auth";
+import { jsonResponse } from "@/lib/api/response";
+
+/**
+ * GET /api/audit-log/filters — distinct filter options for the audit log
+ * viewer (team members and action types actually present in the log).
+ *
+ * Admin only.
+ */
+export const GET = withAuth(async (req, { user }) => {
+  const roleCheck = requireRole(user, "admin");
+  if (roleCheck) return roleCheck;
+
+  const teamUsers = await db
+    .select({ id: users.id, name: users.name, email: users.email })
+    .from(users)
+    .where(user.teamId ? eq(users.teamId, user.teamId) : undefined)
+    .orderBy(users.name);
+
+  const actionRows = await db
+    .selectDistinct({ action: auditLogs.action })
+    .from(auditLogs)
+    .innerJoin(users, eq(auditLogs.userId, users.id))
+    .where(user.teamId ? eq(users.teamId, user.teamId) : undefined)
+    .orderBy(desc(auditLogs.action));
+
+  return jsonResponse({
+    users: teamUsers,
+    actions: actionRows.map((r) => r.action).sort(),
+  });
+});
