+"use client";
+
+import { useState } from "react";
+import { Card, CardContent } from "@/components/ui/card";
+import { AuditLogFiltersBar } from "@/components/audit/audit-log-filters";
+import { AuditLogTable } from "@/components/audit/audit-log-table";
+import { AuditLogTableSkeleton } from "@/components/audit/audit-log-skeleton";
+import { AuditExportButton } from "@/components/audit/audit-export-button";
+import { Button } from "@/components/ui/button";
+import { useAuditLog } from "@/hooks/use-audit-log";
+import { useDateRange } from "@/hooks/use-date-range";
+
+/**
+ * Admin-only audit log viewer.
+ *
+ * Shows who exported what data and when, with filtering by date range,
+ * user, and action type. Admins can also export the audit log itself
+ * (which is, itself, an audited export — see /api/audit-log/export).
+ */
+export default function AuditLogPage() {
+  const { range, setCustomRange } = useDateRange("30d");
+  const [userId, setUserId] = useState<string | undefined>();
+  const [action, setAction] = useState<string | undefined>();
+
+  const { entries, isLoading, isLoadingMore, error, hasMore, loadMore, filterOptions } =
+    useAuditLog({ from: range.from, to: range.to, userId, action });
+
+  const filters = { from: range.from, to: range.to, userId, action };
+
+  const handleClear = () => {
+    setUserId(undefined);
+    setAction(undefined);
+  };
+
+  return (
+    <div className="space-y-6">
+      <div className="flex items-center justify-between">
+        <div>
+          <h2 className="text-2xl font-bold text-gray-900">Audit Log</h2>
+          <p className="text-sm text-gray-500">
+            Track who exported what data, and when.
+          </p>
+        </div>
+        <AuditExportButton filters={filters} />
+      </div>
+
+      <Card>
+        <CardContent className="space-y-4 p-6">
+          <AuditLogFiltersBar
+            from={range.from}
+            to={range.to}
+            userId={userId}
+            action={action}
+            options={filterOptions}
+            onDateRangeChange={({ from, to }) => setCustomRange(from, to)}
+            onUserChange={setUserId}
+            onActionChange={setAction}
+            onClear={handleClear}
+          />
+
+          {error && (
+            <div className="rounded-md border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
+              {error}
+            </div>
+          )}
+
+          {isLoading ? (
+            <AuditLogTableSkeleton />
+          ) : (
+            <>
+              <AuditLogTable entries={entries} />
+              {hasMore && (
+                <div className="flex justify-center pt-2">
+                  <Button
+                    variant="secondary"
+                    onClick={loadMore}
+                    disabled={isLoadingMore}
+                  >
+                    {isLoadingMore ? "Loading..." : "Load more"}
+                  </Button>
+                </div>
+              )}
+            </>
+          )}
+        </CardContent>
+      </Card>
+    </div>
+  );
+}
