@@ -0,0 +1,79 @@
+"use client";
+
+import { Download } from "lucide-react";
+import { Button } from "@/components/ui/button";
+import { useToast } from "@/hooks/use-toast";
+import { useState } from "react";
+import type { AuditLogFilters } from "@/hooks/use-audit-log";
+
+interface AuditExportButtonProps {
+  filters: AuditLogFilters;
+  format?: "csv" | "json";
+}
+
+/**
+ * Export button for the audit log itself.
+ *
+ * IMPORTANT: the server-side `/api/audit-log/export` endpoint uses
+ * `withAuditLog` to comply with data governance policy DG-003 — exporting
+ * the audit log is itself a data export and gets logged like any other.
+ *
+ * Uses variant="secondary" because this is a read-only/export action,
+ * not a mutation. See Button component conventions.
+ */
+export function AuditExportButton({ filters, format = "csv" }: AuditExportButtonProps) {
+  const toast = useToast();
+  const [isExporting, setIsExporting] = useState(false);
+
+  const handleExport = async () => {
+    setIsExporting(true);
+    try {
+      toast.loading("Preparing audit log export...");
+
+      const response = await fetch("/api/audit-log/export", {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify({
+          startDate: filters.from.toISOString(),
+          endDate: filters.to.toISOString(),
+          userId: filters.userId,
+          action: filters.action,
+          format,
+        }),
+      });
+
+      if (!response.ok) {
+        const error = await response.json();
+        toast.error(
+          error.help
+            ? `Export failed. See ${error.help}`
+            : "Export failed. Please try again."
+        );
+        return;
+      }
+
+      const blob = await response.blob();
+      const url = URL.createObjectURL(blob);
+      const a = document.createElement("a");
+      a.href = url;
+      a.download = `audit-log-export.${format}`;
+      a.click();
+      URL.revokeObjectURL(url);
+
+      toast.success("Audit log exported successfully");
+    } catch {
+      toast.error(
+        "Export failed. See https://help.example.com/errors/EXPORT_001"
+      );
+    } finally {
+      setIsExporting(false);
+    }
+  };
+
+  return (
+    <Button variant="secondary" onClick={handleExport} disabled={isExporting}>
+      <Download className="mr-2 h-4 w-4" />
+      {isExporting ? "Exporting..." : "Export Audit Log"}
+    </Button>
+  );
+}
