+"use client";
+
+import { DateRangePicker } from "@/components/ui/date-range-picker";
+import { Select } from "@/components/ui/select";
+import { Label } from "@/components/ui/label";
+import { Button } from "@/components/ui/button";
+import { formatActionLabel } from "@/lib/utils";
+import type { AuditLogFilterOptions } from "@/types/audit-log";
+
+interface AuditLogFiltersProps {
+  from: Date;
+  to: Date;
+  userId?: string;
+  action?: string;
+  options: AuditLogFilterOptions;
+  onDateRangeChange: (range: { from: Date; to: Date }) => void;
+  onUserChange: (userId: string | undefined) => void;
+  onActionChange: (action: string | undefined) => void;
+  onClear: () => void;
+}
+
+/**
+ * Filter bar for the audit log viewer: date range, user, and action type.
+ *
+ * Uses the preferred DateRangePicker (`from`/`to` prop convention) and the
+ * shared Select component, consistent with the rest of the app.
+ */
+export function AuditLogFiltersBar({
+  from,
+  to,
+  userId,
+  action,
+  options,
+  onDateRangeChange,
+  onUserChange,
+  onActionChange,
+  onClear,
+}: AuditLogFiltersProps) {
+  const hasActiveFilters = Boolean(userId || action);
+
+  return (
+    <div className="flex flex-wrap items-end gap-3">
+      <div className="space-y-1">
+        <Label>Date Range</Label>
+        <DateRangePicker
+          from={from}
+          to={to}
+          onSelect={onDateRangeChange}
+          className="w-72"
+        />
+      </div>
+
+      <div className="space-y-1">
+        <Label htmlFor="audit-user-filter">User</Label>
+        <Select
+          id="audit-user-filter"
+          className="w-48"
+          value={userId ?? ""}
+          onChange={(e) => onUserChange(e.target.value || undefined)}
+        >
+          <option value="">All users</option>
+          {options.users.map((u) => (
+            <option key={u.id} value={u.id}>
+              {u.name}
+            </option>
+          ))}
+        </Select>
+      </div>
+
+      <div className="space-y-1">
+        <Label htmlFor="audit-action-filter">Action</Label>
+        <Select
+          id="audit-action-filter"
+          className="w-48"
+          value={action ?? ""}
+          onChange={(e) => onActionChange(e.target.value || undefined)}
+        >
+          <option value="">All actions</option>
+          {options.actions.map((a) => (
+            <option key={a} value={a}>
+              {formatActionLabel(a)}
+            </option>
+          ))}
+        </Select>
+      </div>
+
+      {hasActiveFilters && (
+        <Button variant="ghost" size="md" onClick={onClear}>
+          Clear filters
