+import { Badge } from "@/components/ui/badge";
+import { formatDate, formatActionLabel } from "@/lib/utils";
+import { format } from "date-fns";
+import type { AuditLogEntry } from "@/types/audit-log";
+
+interface AuditLogTableProps {
+  entries: AuditLogEntry[];
+}
+
+/**
+ * Table of audit log entries: who did what, when, and whether it succeeded.
+ */
+export function AuditLogTable({ entries }: AuditLogTableProps) {
+  if (entries.length === 0) {
+    return (
+      <div className="flex flex-col items-center justify-center rounded-lg border border-dashed border-gray-300 py-16 text-center">
+        <p className="text-sm font-medium text-gray-900">No audit log entries found</p>
+        <p className="mt-1 text-sm text-gray-500">
+          Try widening the date range or clearing filters.
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <div className="overflow-hidden rounded-lg border border-gray-200">
+      <table className="w-full text-sm">
+        <thead className="border-b border-gray-200 bg-gray-50">
+          <tr>
+            <th className="px-4 py-3 text-left font-medium text-gray-500">User</th>
+            <th className="px-4 py-3 text-left font-medium text-gray-500">Action</th>
+            <th className="px-4 py-3 text-left font-medium text-gray-500">Resource</th>
+            <th className="px-4 py-3 text-left font-medium text-gray-500">Status</th>
+            <th className="px-4 py-3 text-left font-medium text-gray-500">IP Address</th>
+            <th className="px-4 py-3 text-left font-medium text-gray-500">Date</th>
+          </tr>
+        </thead>
+        <tbody className="divide-y divide-gray-100">
+          {entries.map((entry) => {
+            const status = (entry.metadata?.status as string) || "success";
+            return (
+              <tr key={entry.id} className="hover:bg-gray-50">
+                <td className="px-4 py-3">
+                  <div className="flex items-center gap-2">
+                    <div className="flex h-7 w-7 items-center justify-center rounded-full bg-brand-100 text-xs font-medium text-brand-700">
+                      {initials(entry.userName)}
+                    </div>
+                    <div>
+                      <p className="font-medium text-gray-900">{entry.userName}</p>
+                      <p className="text-xs text-gray-500">{entry.userEmail}</p>
+                    </div>
+                  </div>
+                </td>
+                <td className="px-4 py-3">
+                  <Badge variant="default">{formatActionLabel(entry.action)}</Badge>
+                </td>
+                <td className="px-4 py-3 text-gray-700">
+                  {entry.resourceType}
+                  {entry.resourceId && (
+                    <span className="text-gray-400"> · {entry.resourceId}</span>
+                  )}
+                </td>
+                <td className="px-4 py-3">
+                  <Badge variant={status === "error" ? "error" : "success"}>
+                    {status === "error" ? "Failed" : "Success"}
+                  </Badge>
+                </td>
+                <td className="px-4 py-3 text-gray-500">{entry.ipAddress || "—"}</td>
+                <td className="px-4 py-3 text-gray-500">
+                  <span title={format(new Date(entry.createdAt), "PPpp")}>
+                    {formatDate(entry.createdAt)}
+                  </span>
+                </td>
+              </tr>
+            );
+          })}
+        </tbody>
+      </table>
+    </div>
+  );
+}
+
+function initials(name: string): string {
+  return name
+    .split(" ")
+    .map((part) => part[0])
+    .filter(Boolean)
+    .slice(0, 2)
+    .join("")
+    .toUpperCase();
+}
