+import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
+import { renderHook, waitFor, act } from "@testing-library/react";
+import { useAuditLog } from "./use-audit-log";
+
+const page1 = {
+  data: [
+    {
+      id: "log-1",
+      userId: "user-1",
+      userName: "Sarah Chen",
+      userEmail: "sarah@acme.com",
+      action: "export_analytics",
+      resourceType: "export",
+      resourceId: null,
+      metadata: { status: "success" },
+      ipAddress: "203.0.113.5",
+      createdAt: "2024-06-15T12:00:00.000Z",
+    },
+  ],
+  nextCursor: "cursor-1",
+  hasMore: true,
+};
+
+const page2 = {
+  data: [
+    {
+      id: "log-2",
+      userId: "user-2",
+      userName: "Marcus Rodriguez",
+      userEmail: "marcus@acme.com",
+      action: "export_users",
+      resourceType: "export",
+      resourceId: null,
+      metadata: { status: "success" },
+      ipAddress: "203.0.113.6",
+      createdAt: "2024-06-14T12:00:00.000Z",
+    },
+  ],
+  nextCursor: null,
+  hasMore: false,
+};
+
+function jsonResponse(body: unknown, ok = true) {
+  return Promise.resolve({
+    ok,
+    json: () => Promise.resolve(body),
+  });
+}
+
+describe("useAuditLog", () => {
+  beforeEach(() => {
+    global.fetch = vi.fn((url: string) => {
+      if (url.includes("/api/audit-log/filters")) {
+        return jsonResponse({ users: [], actions: [] });
+      }
+      if (url.includes("cursor=cursor-1")) {
+        return jsonResponse(page2);
+      }
+      return jsonResponse(page1);
+    }) as unknown as typeof fetch;
+  });
+
+  afterEach(() => {
+    vi.restoreAllMocks();
+  });
+
+  it("should start in a loading state", () => {
+    const { result } = renderHook(() =>
+      useAuditLog({ from: new Date("2024-01-01"), to: new Date("2024-01-31") })
+    );
+    expect(result.current.isLoading).toBe(true);
+  });
+
+  it("should load entries and stop loading", async () => {
+    const { result } = renderHook(() =>
+      useAuditLog({ from: new Date("2024-01-01"), to: new Date("2024-01-31") })
+    );
+
+    await waitFor(() => expect(result.current.isLoading).toBe(false));
+    expect(result.current.entries).toHaveLength(1);
+    expect(result.current.entries[0].userName).toBe("Sarah Chen");
+    expect(result.current.hasMore).toBe(true);
+  });
+
+  it("should append entries on loadMore", async () => {
+    const { result } = renderHook(() =>
+      useAuditLog({ from: new Date("2024-01-01"), to: new Date("2024-01-31") })
+    );
+
+    await waitFor(() => expect(result.current.isLoading).toBe(false));
+
+    await act(async () => {
+      result.current.loadMore();
+    });
+
+    await waitFor(() => expect(result.current.entries).toHaveLength(2));
+    expect(result.current.hasMore).toBe(false);
+  });
+
+  it("should set an error message when the request fails", async () => {
+    global.fetch = vi.fn().mockResolvedValue({
+      ok: false,
+      json: () => Promise.resolve({ help: "https://help.example.com/errors/VAL_001" }),
+    });
+
+    const { result } = renderHook(() =>
+      useAuditLog({ from: new Date("2024-01-01"), to: new Date("2024-01-31") })
+    );
+
+    await waitFor(() => expect(result.current.isLoading).toBe(false));
+    expect(result.current.error).toContain("https://help.example.com/errors/VAL_001");
+  });
+
+  it("should refetch from scratch when filters change", async () => {
+    const { result, rerender } = renderHook(
+      ({ userId }: { userId?: string }) =>
+        useAuditLog({
+          from: new Date("2024-01-01"),
+          to: new Date("2024-01-31"),
+          userId,
+        }),
+      { initialProps: { userId: undefined as string | undefined } }
+    );
+
+    await waitFor(() => expect(result.current.isLoading).toBe(false));
+    const fetchCallsBefore = (global.fetch as ReturnType<typeof vi.fn>).mock.calls.length;
+
+    rerender({ userId: "user-1" });
+
+    await waitFor(() =>
+      expect((global.fetch as ReturnType<typeof vi.fn>).mock.calls.length).toBeGreaterThan(
+        fetchCallsBefore
+      )
+    );
+  });
+});
