@@ -0,0 +1,132 @@
+"use client";
+
+import { useCallback, useEffect, useRef, useState } from "react";
+import type { AuditLogEntry, AuditLogFilterOptions } from "@/types/audit-log";
+
+export interface AuditLogFilters {
+  from: Date;
+  to: Date;
+  userId?: string;
+  action?: string;
+}
+
+interface UseAuditLogResult {
+  entries: AuditLogEntry[];
+  isLoading: boolean;
+  isLoadingMore: boolean;
+  error: string | null;
+  hasMore: boolean;
+  loadMore: () => void;
+  filterOptions: AuditLogFilterOptions;
+}
+
+/**
+ * Fetches audit log entries for the admin audit log viewer.
+ *
+ * Uses the cursor-based pagination convention (see `src/lib/api/pagination.ts`).
+ * Re-fetches from scratch whenever the filters change.
+ */
+export function useAuditLog(filters: AuditLogFilters): UseAuditLogResult {
+  const [entries, setEntries] = useState<AuditLogEntry[]>([]);
+  const [cursor, setCursor] = useState<string | null>(null);
+  const [hasMore, setHasMore] = useState(false);
+  const [isLoading, setIsLoading] = useState(true);
+  const [isLoadingMore, setIsLoadingMore] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const [filterOptions, setFilterOptions] = useState<AuditLogFilterOptions>({
+    users: [],
+    actions: [],
+  });
+
+  const requestId = useRef(0);
+
+  const buildQuery = useCallback(
+    (cursorParam?: string) => {
+      const params = new URLSearchParams({
+        startDate: filters.from.toISOString(),
+        endDate: filters.to.toISOString(),
+        limit: "20",
+      });
+      if (filters.userId) params.set("userId", filters.userId);
+      if (filters.action) params.set("action", filters.action);
+      if (cursorParam) params.set("cursor", cursorParam);
+      return params.toString();
+    },
+    // Depend on timestamps (not Date identity) so callers that derive a new
+    // Date instance with the same value on every render don't trigger a
+    // re-fetch loop.
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+    [filters.from.getTime(), filters.to.getTime(), filters.userId, filters.action]
+  );
+
+  useEffect(() => {
+    const currentRequest = ++requestId.current;
+    setIsLoading(true);
+    setError(null);
+
+    fetch(`/api/audit-log?${buildQuery()}`)
+      .then(async (res) => {
+        if (currentRequest !== requestId.current) return;
+        if (!res.ok) {
+          const body = await res.json().catch(() => null);
+          throw new Error(
+            body?.help ? `Failed to load audit log. See ${body.help}` : "Failed to load audit log."
+          );
+        }
+        return res.json();
+      })
+      .then((page) => {
+        if (!page || currentRequest !== requestId.current) return;
+        setEntries(page.data);
+        setCursor(page.nextCursor);
+        setHasMore(page.hasMore);
+      })
+      .catch((err: Error) => {
+        if (currentRequest !== requestId.current) return;
+        setError(err.message);
+      })
+      .finally(() => {
+        if (currentRequest !== requestId.current) return;
+        setIsLoading(false);
+      });
+  }, [buildQuery]);
+
+  useEffect(() => {
+    fetch("/api/audit-log/filters")
+      .then((res) => (res.ok ? res.json() : null))
+      .then((data) => {
+        if (data) setFilterOptions(data);
+      })
+      .catch(() => {
+        // Filter options are a progressive enhancement; ignore failures.
+      });
+  }, []);
+
+  const loadMore = useCallback(() => {
+    if (!cursor || isLoadingMore) return;
+    setIsLoadingMore(true);
+    fetch(`/api/audit-log?${buildQuery(cursor)}`)
+      .then(async (res) => {
+        if (!res.ok) {
+          const body = await res.json().catch(() => null);
+          throw new Error(
+            body?.help ? `Failed to load more entries. See ${body.help}` : "Failed to load more entries."
+          );
+        }
+        return res.json();
+      })
+      .then((page) => {
+        setEntries((prev) => [...prev, ...page.data]);
+        setCursor(page.nextCursor);
+        setHasMore(page.hasMore);
+      })
+      .catch((err: Error) => {
+        setError(err.message);
+      })
+      .finally(() => {
+        setIsLoadingMore(false);
+      });
+  }, [buildQuery, cursor, isLoadingMore]);
+
+  return { entries, isLoading, isLoadingMore, error, hasMore, loadMore, filterOptions };
+}
