+import { NextRequest } from "next/server";
+import { db } from "@/lib/db";
+import { analyticsEvents } from "@/lib/db/schema";
+import { eq, and, gte, lte, count } from "drizzle-orm";
+import { withAuth } from "@/lib/auth/with-auth";
+import { exportPreviewSchema, MAX_EXPORT_ROWS } from "@/lib/validators/analytics";
+import { errorResponse } from "@/lib/errors";
+import { jsonResponse } from "@/lib/api/response";
+
+/**
+ * GET /api/analytics/export/preview — count how many records a would-be
+ * export matches for a given date range, without returning any record data.
+ *
+ * This lets the UI show "X records will be exported" before the user
+ * commits to a download.
+ *
+ * NOTE: This endpoint intentionally does NOT go through `withAuditLog`.
+ * DG-003 requires auditing of data exports (endpoints that return actual
+ * record data); this endpoint only returns an aggregate count, so no
+ * underlying data leaves the system. The real export at
+ * POST /api/analytics/export remains the audited endpoint.
+ */
+export const GET = withAuth(async (req, { user }) => {
+  const url = new URL(req.url);
+  const eventTypesParam = url.searchParams.get("eventTypes");
+
+  const parsed = exportPreviewSchema.safeParse({
+    startDate: url.searchParams.get("startDate") || undefined,
+    endDate: url.searchParams.get("endDate") || undefined,
+    eventTypes: eventTypesParam ? eventTypesParam.split(",") : undefined,
+  });
+
+  if (!parsed.success) {
+    return errorResponse("VAL_001", 400, parsed.error.issues[0].message);
+  }
+
+  const { startDate, endDate, eventTypes } = parsed.data;
+
+  const conditions = [];
+
+  if (user.teamId) {
+    conditions.push(eq(analyticsEvents.teamId, user.teamId));
+  }
+  conditions.push(gte(analyticsEvents.createdAt, startDate));
+  conditions.push(lte(analyticsEvents.createdAt, endDate));
+
+  if (eventTypes && eventTypes.length > 0) {
+    // Mirrors the export route's event type filtering (currently single-type).
+    conditions.push(eq(analyticsEvents.eventType, eventTypes[0]));
+  }
+
+  const [{ total }] = await db
+    .select({ total: count() })
+    .from(analyticsEvents)
+    .where(and(...conditions));
+
+  return jsonResponse({
+    count: total,
+    exceedsLimit: total > MAX_EXPORT_ROWS,
+    limit: MAX_EXPORT_ROWS,
+  });
+});
