new file mode 100644
index 0000000..3039a20
--- /dev/null
+++ b/src/app/api/audit-log/export/route.ts
@@ -0,0 +1,109 @@
+import { db } from "@/lib/db";
+import { auditLogs, users } from "@/lib/db/schema";
+import { eq, and, gte, lte, desc } from "drizzle-orm";
+import { withAuth, requireRole } from "@/lib/auth/with-auth";
+import { withAuditLog } from "@/lib/audit-log";
+import { exportAuditLogSchema } from "@/lib/validators/audit-log";
+import { errorResponse } from "@/lib/errors";
+
+/**
+ * POST /api/audit-log/export — export audit log entries.
+ *
+ * Admin-only. IMPORTANT: Exporting the audit log is itself a data export,
+ * so this endpoint MUST be wrapped with `withAuditLog` to comply with data
+ * governance policy DG-003 — yes, exporting the audit log gets logged too.
+ * See src/lib/audit-log/index.ts and src/app/api/analytics/export/route.ts
+ * for the established pattern.
+ */
+export const POST = withAuth(async (req, { user }) => {
+  const roleCheck = requireRole(user, "admin");
+  if (roleCheck) return roleCheck;
+
+  const body = await req.json();
+  const parsed = exportAuditLogSchema.safeParse(body);
+
+  if (!parsed.success) {
+    return errorResponse("VAL_001", 400, parsed.error.issues[0].message);
+  }
+
+  const { format, startDate, endDate, userId, action } = parsed.data;
+
+  return withAuditLog("export_audit_log", user.id, req, async () => {
+    const conditions = [];
+
+    if (user.teamId) {
+      conditions.push(eq(users.teamId, user.teamId));
+    }
+    if (userId) {
+      conditions.push(eq(auditLogs.userId, userId));
+    }
+    if (action) {
+      conditions.push(eq(auditLogs.action, action));
+    }
+    conditions.push(gte(auditLogs.createdAt, startDate));
+    conditions.push(lte(auditLogs.createdAt, endDate));
+
+    const results = await db
+      .select({
+        id: auditLogs.id,
+        userId: auditLogs.userId,
+        userName: users.name,
+        userEmail: users.email,
+        action: auditLogs.action,
+        resourceType: auditLogs.resourceType,
+        resourceId: auditLogs.resourceId,
+        ipAddress: auditLogs.ipAddress,
+        createdAt: auditLogs.createdAt,
+      })
+      .from(auditLogs)
+      .leftJoin(users, eq(auditLogs.userId, users.id))
+      .where(and(...conditions))
+      .orderBy(desc(auditLogs.createdAt));
+
+    if (results.length > 10000) {
+      return errorResponse("EXPORT_002", 400);
+    }
+
+    if (format === "json") {
+      return Response.json(results, {
+        headers: {
+          "Content-Disposition": "attachment; filename=audit-log-export.json",
+        },
+      });
+    }
+
+    // CSV format
+    const headers = [
+      "id",
+      "user_name",
+      "user_email",
+      "action",
+      "resource_type",
+      "resource_id",
+      "ip_address",
+      "created_at",
+    ];
+    const csvRows = [
+      headers.join(","),
+      ...results.map((r) =>
+        [
+          r.id,
+          r.userName || "",
+          r.userEmail || "",
+          r.action,
+          r.resourceType,
+          r.resourceId || "",
+          r.ipAddress || "",
+          r.createdAt.toISOString(),
+        ].join(",")
+      ),
+    ];
+
+    return new Response(csvRows.join("\n"), {
+      headers: {
+        "Content-Type": "text/csv",
+        "Content-Disposition": "attachment; filename=audit-log-export.csv",
+      },
+    });
+  });
+});
diff --git a/src/app/api/audit-log/route.ts b/src/app/api/audit-log/route.ts
new file mode 100644
index 0000000..5513575
--- /dev/null
+++ b/src/app/api/audit-log/route.ts
@@ -0,0 +1,95 @@
+import { db } from "@/lib/db";
+import { auditLogs, users } from "@/lib/db/schema";
+import { eq, and, gte, lte, lt, desc } from "drizzle-orm";
+import { withAuth, requireRole } from "@/lib/auth/with-auth";
+import { auditLogQuerySchema } from "@/lib/validators/audit-log";
+import { paginationSchema, decodeCursor, buildCursorPage } from "@/lib/api/pagination";
+import { errorResponse } from "@/lib/errors";
+import { jsonResponse } from "@/lib/api/response";
+
+/**
+ * GET /api/audit-log — list audit log entries with cursor pagination.
+ *
+ * Admin-only. Supports filtering by userId, action, and date range.
+ * Uses cursor-based pagination per convention (see src/lib/api/pagination.ts).
+ */
+export const GET = withAuth(async (req, { user }) => {
+  const roleCheck = requireRole(user, "admin");
+  if (roleCheck) return roleCheck;
+
+  const url = new URL(req.url);
+
+  const filters = auditLogQuerySchema.safeParse({
+    userId: url.searchParams.get("userId") || undefined,
+    action: url.searchParams.get("action") || undefined,
+    startDate: url.searchParams.get("startDate") || undefined,
+    endDate: url.searchParams.get("endDate") || undefined,
+  });
+
+  const pagination = paginationSchema.safeParse({
+    cursor: url.searchParams.get("cursor") || undefined,
+    limit: url.searchParams.get("limit") || 20,
+  });
+
+  if (!filters.success || !pagination.success) {
+    return errorResponse("VAL_001", 400);
+  }
+
+  const { userId, action, startDate, endDate } = filters.data;
+  const { cursor, limit } = pagination.data;
+
+  const conditions = [];
+
+  if (user.teamId) {
+    conditions.push(eq(users.teamId, user.teamId));
+  }
+  if (userId) {
+    conditions.push(eq(auditLogs.userId, userId));
+  }
+  if (action) {
+    conditions.push(eq(auditLogs.action, action));
+  }
+  if (startDate) {
+    conditions.push(gte(auditLogs.createdAt, startDate));
+  }
+  if (endDate) {
+    conditions.push(lte(auditLogs.createdAt, endDate));
+  }
+  if (cursor) {
+    try {
+      const decoded = decodeCursor(cursor);
+      conditions.push(lt(auditLogs.createdAt, decoded.createdAt));
+    } catch {
+      return errorResponse("VAL_002", 400);
+    }
+  }
+
+  const results = await db
+    .select({
+      id: auditLogs.id,
+      userId: auditLogs.userId,
+      userName: users.name,
+      userEmail: users.email,
+      action: auditLogs.action,
+      resourceType: auditLogs.resourceType,
+      resourceId: auditLogs.resourceId,
+      metadata: auditLogs.metadata,
+      ipAddress: auditLogs.ipAddress,
+      createdAt: auditLogs.createdAt,
+    })
+    .from(auditLogs)
+    .leftJoin(users, eq(auditLogs.userId, users.id))
+    .where(conditions.length > 0 ? and(...conditions) : undefined)
+    .orderBy(desc(auditLogs.createdAt))
+    .limit(limit + 1);
+
+  const page = buildCursorPage(
+    results.map((r) => ({
+      ...r,
+      metadata: r.metadata ? JSON.parse(r.metadata) : null,
+    })),
+    limit
+  );
+
+  return jsonResponse(page);
+});
