+  const [entries, setEntries] = useState<AuditLogEntry[]>([]);
+  const [userOptions, setUserOptions] = useState<AuditLogUserOption[]>([]);
+  const [cursor, setCursor] = useState<string | null>(null);
+  const [hasMore, setHasMore] = useState(false);
+  const [isLoading, setIsLoading] = useState(true);
+  const [isLoadingMore, setIsLoadingMore] = useState(false);
+  const [forbidden, setForbidden] = useState(false);
+
+  const fetchEntries = useCallback(
+    async (nextCursor: string | null, append: boolean) => {
+      if (append) {
+        setIsLoadingMore(true);
+      } else {
+        setIsLoading(true);
+        setForbidden(false);
+      }
+
+      try {
+        const params = new URLSearchParams({
+          startDate: range.from.toISOString(),
+          endDate: range.to.toISOString(),
+        });
+        if (userId) params.set("userId", userId);
+        if (action) params.set("action", action);
+        if (nextCursor) params.set("cursor", nextCursor);
+
+        const response = await fetch(`/api/audit-log?${params.toString()}`);
+
+        if (response.status === 403) {
+          setForbidden(true);
+          setEntries([]);
+          return;
+        }
+
+        if (!response.ok) {
+          return;
+        }
+
+        const page: PaginatedResponse<AuditLogEntry> = await response.json();
+        setEntries((prev) => (append ? [...prev, ...page.data] : page.data));
+        setCursor(page.nextCursor);
+        setHasMore(page.hasMore);
+      } finally {
+        setIsLoading(false);
+        setIsLoadingMore(false);
+      }
+    },
+    [range.from, range.to, userId, action]
+  );
+
+  useEffect(() => {
+    fetchEntries(null, false);
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [range.from, range.to, userId, action]);
+
+  useEffect(() => {
+    fetch("/api/users?limit=100")
+      .then((res) => (res.ok ? res.json() : null))
+      .then((page: PaginatedResponse<AuditLogUserOption> | null) => {
+        if (page) setUserOptions(page.data);
+      })
+      .catch(() => {});
+  }, []);
+
+  if (forbidden) {
+    return (
+      <div className="flex h-64 flex-col items-center justify-center gap-3 text-center">
+        <ShieldAlert className="h-10 w-10 text-gray-400" />
+        <p className="text-sm font-medium text-gray-900">
+          You don&apos;t have permission to view the audit log.
+        </p>
+        <p className="text-sm text-gray-500">
+          This page is restricted to admins.
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <div className="space-y-6">
+      <div className="flex items-center justify-between">
+        <div>
+          <h2 className="text-2xl font-bold text-gray-900">Audit Log</h2>
+          <p className="text-sm text-gray-500">
+            Track who exported what data, and when.
+          </p>
+        </div>
+        {/* variant="secondary" for read-only/export action */}
+        <AuditLogExportButton
+          startDate={range.from}
+          endDate={range.to}
+          userId={userId}
+          action={action}
+        />
+      </div>
+
+      <AuditLogFilters
+        from={range.from}
+        to={range.to}
+        onDateRangeChange={({ from, to }) => setCustomRange(from, to)}
+        userId={userId}
+        onUserChange={setUserId}
+        userOptions={userOptions}
+        action={action}
+        onActionChange={setAction}
+        actionOptions={AUDIT_ACTIONS}
+        disabled={isLoading}
+      />
+
+      <AuditLogTable entries={entries} isLoading={isLoading} />
+
+      {!isLoading && hasMore && (
+        <div className="flex justify-center">
+          <Button
+            variant="secondary"
+            onClick={() => fetchEntries(cursor, true)}
+            disabled={isLoadingMore}
+          >
+            {isLoadingMore ? "Loading..." : "Load more"}
+          </Button>
+        </div>
+      )}
+    </div>
+  );
+}
