+"use client";
+
+import { DateRangePicker } from "@/components/ui/date-range-picker";
+import { Select } from "@/components/ui/select";
+import { Label } from "@/components/ui/label";
+
+export interface AuditLogUserOption {
+  id: string;
+  name: string;
+  email: string;
+}
+
+interface AuditLogFiltersProps {
+  from: Date;
+  to: Date;
+  onDateRangeChange: (range: { from: Date; to: Date }) => void;
+  userId: string;
+  onUserChange: (userId: string) => void;
+  userOptions: AuditLogUserOption[];
+  action: string;
+  onActionChange: (action: string) => void;
+  actionOptions: readonly string[];
+  disabled?: boolean;
+}
+
+/**
+ * Filter controls for the audit log viewer: date range, user, and action type.
+ *
+ * Uses DateRangePicker (from/to props) — the preferred date range component.
+ * Do NOT use the deprecated CalendarRange (startDate/endDate props).
+ */
+export function AuditLogFilters({
+  from,
+  to,
+  onDateRangeChange,
+  userId,
+  onUserChange,
+  userOptions,
+  action,
+  onActionChange,
+  actionOptions,
+  disabled = false,
+}: AuditLogFiltersProps) {
+  return (
+    <div className="flex flex-wrap items-end gap-3">
+      <div>
+        <Label htmlFor="audit-log-date-range" className="mb-1 block">
+          Date range
+        </Label>
+        <DateRangePicker
+          from={from}
+          to={to}
+          onSelect={onDateRangeChange}
+          disabled={disabled}
+          className="w-72"
+        />
+      </div>
+
+      <div>
+        <Label htmlFor="audit-log-user-filter" className="mb-1 block">
+          User
+        </Label>
+        <Select
+          id="audit-log-user-filter"
+          value={userId}
+          onChange={(e) => onUserChange(e.target.value)}
+          disabled={disabled}
+          className="w-56"
+        >
+          <option value="">All users</option>
+          {userOptions.map((u) => (
+            <option key={u.id} value={u.id}>
+              {u.name} ({u.email})
+            </option>
+          ))}
+        </Select>
+      </div>
+
+      <div>
+        <Label htmlFor="audit-log-action-filter" className="mb-1 block">
+          Action type
+        </Label>
+        <Select
+          id="audit-log-action-filter"
+          value={action}
+          onChange={(e) => onActionChange(e.target.value)}
+          disabled={disabled}
+          className="w-52"
+        >
+          <option value="">All actions</option>
+          {actionOptions.map((a) => (
+            <option key={a} value={a}>
+              {a}
+            </option>
+          ))}
+        </Select>
+      </div>
+    </div>
+  );
+}
