+"use client";
+
+import { ShimmerSkeleton } from "@/components/ui/shimmer-skeleton";
+import { Badge } from "@/components/ui/badge";
+import { formatDate } from "@/lib/utils";
+import type { AuditLogEntry } from "@/types/audit-log";
+
+interface AuditLogTableProps {
+  entries: AuditLogEntry[];
+  isLoading?: boolean;
+}
+
+const SKELETON_ROWS = 8;
+
+/**
+ * Table of audit log entries — who exported what data, and when.
+ *
+ * Uses ShimmerSkeleton (the preferred loading pattern) for placeholder
+ * rows while data is being fetched. Do NOT use the deprecated PulseLoader.
+ */
+export function AuditLogTable({ entries, isLoading = false }: AuditLogTableProps) {
+  return (
+    <div className="overflow-hidden rounded-lg border border-gray-200 bg-white">
+      <table className="min-w-full divide-y divide-gray-200">
+        <thead className="bg-gray-50">
+          <tr>
+            <th scope="col" className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+              User
+            </th>
+            <th scope="col" className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+              Action
+            </th>
+            <th scope="col" className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+              Resource
+            </th>
+            <th scope="col" className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+              Status
+            </th>
+            <th scope="col" className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+              IP Address
+            </th>
+            <th scope="col" className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
+              Date
+            </th>
+          </tr>
+        </thead>
+        <tbody className="divide-y divide-gray-100">
+          {isLoading &&
+            Array.from({ length: SKELETON_ROWS }).map((_, i) => (
+              <tr key={`skeleton-${i}`}>
+                <td className="px-4 py-3">
+                  <ShimmerSkeleton variant="text" width="70%" />
+                </td>
+                <td className="px-4 py-3">
+                  <ShimmerSkeleton variant="text" width="50%" />
+                </td>
+                <td className="px-4 py-3">
+                  <ShimmerSkeleton variant="text" width="60%" />
+                </td>
+                <td className="px-4 py-3">
+                  <ShimmerSkeleton variant="rectangular" width="60px" height="20px" />
+                </td>
+                <td className="px-4 py-3">
+                  <ShimmerSkeleton variant="text" width="40%" />
+                </td>
+                <td className="px-4 py-3">
+                  <ShimmerSkeleton variant="text" width="80%" />
+                </td>
+              </tr>
+            ))}
+
+          {!isLoading && entries.length === 0 && (
+            <tr>
+              <td colSpan={6} className="px-4 py-10 text-center text-sm text-gray-500">
+                No audit log entries match your filters.
+              </td>
+            </tr>
+          )}
+
+          {!isLoading &&
+            entries.map((entry) => {
+              const status =
+                typeof entry.metadata?.status === "string"
+                  ? (entry.metadata.status as string)
+                  : null;
+
+              return (
+                <tr key={entry.id} className="hover:bg-gray-50">
+                  <td className="whitespace-nowrap px-4 py-3 text-sm">
+                    <div className="font-medium text-gray-900">
+                      {entry.userName || "Unknown user"}
+                    </div>
+                    <div className="text-gray-500">{entry.userEmail}</div>
+                  </td>
+                  <td className="whitespace-nowrap px-4 py-3 text-sm text-gray-700">
+                    {entry.action}
+                  </td>
+                  <td className="whitespace-nowrap px-4 py-3 text-sm text-gray-700">
+                    {entry.resourceType}
+                    {entry.resourceId ? ` (${entry.resourceId})` : ""}
+                  </td>
+                  <td className="whitespace-nowrap px-4 py-3 text-sm">
+                    {status === "success" && <Badge variant="success">Success</Badge>}
+                    {status === "error" && <Badge variant="error">Error</Badge>}
+                    {!status && <Badge variant="neutral">Unknown</Badge>}
+                  </td>
+                  <td className="whitespace-nowrap px-4 py-3 text-sm text-gray-500">
+                    {entry.ipAddress || "—"}
+                  </td>
+                  <td className="whitespace-nowrap px-4 py-3 text-sm text-gray-500">
+                    {formatDate(entry.createdAt)}
+                  </td>
+                </tr>
+              );
+            })}
+        </tbody>
+      </table>
+    </div>
+  );
+}
